INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (24, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/pry.jpg" alt="Photo of Carl Pry" />Carl Pry is a Certified Regulatory Compliance Manager (CRCM) and Certified Risk Professional (CRP) who is a Senior Director for Treliant Risk Advisors in Washington, DC. Through his working career, as well as through his experience as a banking attorney and officer, he has provided a variety of regulatory compliance and financial performance services to financial institutions and other clients throughout the country. He has written extensively regarding consumer and commercial compliance, tax, audit, and financial institution legal issues, and is a frequent contributor to and currently serves on the Editorial Advisory Board for the ABA Bank Compliance magazine. He has spoken at dozens of banking, compliance, and state bar associations, and has conducted training sessions for financial institutions across the country.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/pry.jpg" alt="Photo of Carl Pry" />Carl Pry is a Certified Regulatory Compliance Manager (CRCM) and Certified Risk Professional (CRP) who is a Senior Director for Treliant Risk Advisors in Washington, DC. Through his working career, as well as through his experience as a banking attorney and officer, he has provided a variety of regulatory compliance and financial performance services to financial institutions and other clients throughout the country. He has written extensively regarding consumer and commercial compliance, tax, audit, and financial institution legal issues, and is a frequent contributor to and currently serves on the Editorial Advisory Board for the ABA Bank Compliance magazine. He has spoken at dozens of banking, compliance, and state bar associations, and has conducted training sessions for financial institutions across the country.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/pry.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/pry.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (25, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/shelton.jpg" alt="Photo of Honey Shelton" />Honey Shelton brings the best of both worlds to her speaking and training engagements. She has 25 years of experience as a training and quality improvement consultant for banks and banking associations across the country. Her banking background includes spending three years as Executive Vice President/Chief Retail Banking Officer with First Victoria National Bank. </p> <p>Nationally recognized as an outstanding speaker, over a half million bankers have participated in programs Honey has presented. Her depth of knowledge, enthusiasm, and compelling personality has left her lasting mark on InterAction Training, the firm she founded in 1983. </p><p>As a graduate of the School of Bank Marketing from the University of Colorado, she realizes the value of quality education. Honey invests time as a faculty member for banking schools around the country. She is a repeat presenter for most of the state banking associations. </p><p>Honey continues in her own personal pursuit of excellence and is a member of the American Society of Training and Development (ASTD). Currently she is pursuing a self study program on Six Sigma. She has obtained certification in Reality Therapy from the William Glasser Institute as well as certification from the Training and Development Program at Texas A &amp; M. </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/shelton.jpg" alt="Photo of Honey Shelton" />Honey Shelton brings the best of both worlds to her speaking and training engagements. She has 25 years of experience as a training and quality improvement consultant for banks and banking associations across the country. Her banking background includes spending three years as Executive Vice President/Chief Retail Banking Officer with First Victoria National Bank. </p> <p>Nationally recognized as an outstanding speaker, over a half million bankers have participated in programs Honey has presented. Her depth of knowledge, enthusiasm, and compelling personality has left her lasting mark on InterAction Training, the firm she founded in 1983. </p><p>As a graduate of the School of Bank Marketing from the University of Colorado, she realizes the value of quality education. Honey invests time as a faculty member for banking schools around the country. She is a repeat presenter for most of the state banking associations. </p><p>Honey continues in her own personal pursuit of excellence and is a member of the American Society of Training and Development (ASTD). Currently she is pursuing a self study program on Six Sigma. She has obtained certification in Reality Therapy from the William Glasser Institute as well as certification from the Training and Development Program at Texas A &amp; M. </p>', N'https://ttseast.blob.core.windows.net/images/presenters/shelton.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/shelton.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (27, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/dicara.jpg" alt="Photo of Vin DiCara" />Vincent DiCara is currently the owner of DiCara Training and Consulting LLC which he established in January of 2013.&nbsp; Formerly, he was the co-owner and founder of Development Finance Training and Consulting, Inc. (DFTC) which he established in 2003.&nbsp; Mr. DiCara has been involved in evaluating the credit needs of businesses for thirty years as a business advocate, lender, credit analyst and trainer.&nbsp; Since 1995, Mr. DiCara has developed and conducted a wide variety of training programs for individuals who work in the financial services industry sector.&nbsp; His training clients include organizations in the credit union, banking, economic development, and community development fields.&nbsp; Mr. DiCaras training programs have become known for their ability to foster an informal and participatory environment in which students are empowered to learn.</p><p>Mr. DiCara is a graduate of Bowdoin College in Brunswick, Maine and received a Masters Degree in Public Administration from the University of Maine.&nbsp; A native of Boston, Massachusetts, he has been a resident of the State of Maine for the last thirty-eight years.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/dicara.jpg" alt="Photo of Vin DiCara" />Vincent DiCara is currently the owner of DiCara Training and Consulting LLC which he established in January of 2013.&nbsp; Formerly, he was the co-owner and founder of Development Finance Training and Consulting, Inc. (DFTC) which he established in 2003.&nbsp; Mr. DiCara has been involved in evaluating the credit needs of businesses for thirty years as a business advocate, lender, credit analyst and trainer.&nbsp; Since 1995, Mr. DiCara has developed and conducted a wide variety of training programs for individuals who work in the financial services industry sector.&nbsp; His training clients include organizations in the credit union, banking, economic development, and community development fields.&nbsp; Mr. DiCaras training programs have become known for their ability to foster an informal and participatory environment in which students are empowered to learn.</p><p>Mr. DiCara is a graduate of Bowdoin College in Brunswick, Maine and received a Masters Degree in Public Administration from the University of Maine.&nbsp; A native of Boston, Massachusetts, he has been a resident of the State of Maine for the last thirty-eight years.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/dicara.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/dicara.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (28, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/konarik.jpg" alt="Photo of Patrice Konarik" />Patrice M. Konarik, is president and founder of Sunwest Training Corp. located in the Texas Hill Country near San Antonio, Texas. With over 30 years experience in the financial industry, Patrice has focused her expertise on the retirement and new account areas and is currently providing live training and webinars on these subjects on a nationwide basis. She has a BS in Management Science from New Yorks Binghamton University. &nbsp;Many state banking associations and other organizations use her as their main source for training on these complicated topics. Patrices upbeat personality and former banking experience easily encourages interaction and questions during the training sessions.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/konarik.jpg" alt="Photo of Patrice Konarik" />Patrice M. Konarik, is president and founder of Sunwest Training Corp. located in the Texas Hill Country near San Antonio, Texas. With over 30 years experience in the financial industry, Patrice has focused her expertise on the retirement and new account areas and is currently providing live training and webinars on these subjects on a nationwide basis. She has a BS in Management Science from New Yorks Binghamton University. &nbsp;Many state banking associations and other organizations use her as their main source for training on these complicated topics. Patrices upbeat personality and former banking experience easily encourages interaction and questions during the training sessions.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/konarik.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/konarik.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (30, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/brissette.jpg" alt="Photo of Tony Brissette" />$Tony Brissette is President of Brissette Consulting Services, Inc., located in Shrewsbury , MA . Brissette Co nsulting Services, Inc. specializes in Bank Security, Bank Security Training Programs and White Collar Crime. As a licensed private investigator, Tony was Director of Security for Worcester County Institution for Savings; Manager of Investigations for BankBoston and prior to leaving BankBoston was appointed Corporate Security Training Officer. Tony is a Certified Fraud Examiner and was the Center for Financial Training Teacher of the Year in 2000. ', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/brissette.jpg" alt="Photo of Tony Brissette" />$Tony Brissette is President of Brissette Consulting Services, Inc., located in Shrewsbury , MA . Brissette Co nsulting Services, Inc. specializes in Bank Security, Bank Security Training Programs and White Collar Crime. As a licensed private investigator, Tony was Director of Security for Worcester County Institution for Savings; Manager of Investigations for BankBoston and prior to leaving BankBoston was appointed Corporate Security Training Officer. Tony is a Certified Fraud Examiner and was the Center for Financial Training Teacher of the Year in 2000. ', N'https://ttseast.blob.core.windows.net/images/presenters/brissette.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/brissette.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (32, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/herrman.jpg" alt="Photo of Al Herrman" />Al Herrman is a dynamic presenter and trainer with over 20 years experience in training and education, including 12 years within the financial services industry where he trained and managed training departments that focused on the retail service and sales aspects of the industry. His company, Al Herrman Training & Management Consulting, is located in St. Louis, Missouri, and specializes in helping organizations effectively improve and manage employee performance.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/herrman.jpg" alt="Photo of Al Herrman" />Al Herrman is a dynamic presenter and trainer with over 20 years experience in training and education, including 12 years within the financial services industry where he trained and managed training departments that focused on the retail service and sales aspects of the industry. His company, Al Herrman Training & Management Consulting, is located in St. Louis, Missouri, and specializes in helping organizations effectively improve and manage employee performance.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/herrman.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/herrman.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10563, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/laboda.jpg" alt="Photo of Adam LaBoda" />Adam LaBoda, Esq. is a Partner with Spencer Fane Britt &amp; Browne LLP where he specializes in the representation of financial institutions.</p><p>Adam was awarded his juris doctor from the University of Kansas Law School. Prior to joining Spencer Fane, Adam served as a law clerk for Chief Judge Lee M. Jackwig, United States Bankruptcy Court for the Southern District of Iowa. He is a member of the Missouri Bar and the Kansas Bar Associations, as well as a member of the Kansas and Missouri Bankers Associations, and the Kansas City Bankruptcy Bar Association. He is licensed to practice law in Missouri and Kansas, as well as the federal district courts in Kansas and the Western District of Missouri.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/laboda.jpg" alt="Photo of Adam LaBoda" />Adam LaBoda, Esq. is a Partner with Spencer Fane Britt &amp; Browne LLP where he specializes in the representation of financial institutions.</p><p>Adam was awarded his juris doctor from the University of Kansas Law School. Prior to joining Spencer Fane, Adam served as a law clerk for Chief Judge Lee M. Jackwig, United States Bankruptcy Court for the Southern District of Iowa. He is a member of the Missouri Bar and the Kansas Bar Associations, as well as a member of the Kansas and Missouri Bankers Associations, and the Kansas City Bankruptcy Bar Association. He is licensed to practice law in Missouri and Kansas, as well as the federal district courts in Kansas and the Western District of Missouri.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/laboda.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/laboda.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10564, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/annthomas.jpg " alt="Photo of Ann Thomas" />Ann Thomas has thirty years of experience in bank accounting and control. She received a BA in Accounting from the University of Houston in 1982. From 1982 through 1997 she worked with Judith Alexander Jenkins, as Alexander & Associates and subsequently Alexander & Leavelle, providing planning, financial reporting, regulatory reporting, and operational and compliance auditing services to over ninety independent banks.</p><p> In 1998, she organized Thomas Consulting. At Thomas Consulting she now prepares bank plans, monthly financial reports, performs regulatory compliance audits and training and internal control audits for several banks. Additionally, she prepares and reviews Call Reports for several banks. Ms. Thomas has taught numerous call report seminars for state banking associations.</p><p> She has presented the Call Report Seminar to and has responded to questions from thousands of bankers in over 16 states. Her experience in working with a broad range of independent financial institutions is of unique value in understanding Call Report questions and in communicating with bankers in their language.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/annthomas.jpg " alt="Photo of Ann Thomas" />Ann Thomas has thirty years of experience in bank accounting and control. She received a BA in Accounting from the University of Houston in 1982. From 1982 through 1997 she worked with Judith Alexander Jenkins, as Alexander & Associates and subsequently Alexander & Leavelle, providing planning, financial reporting, regulatory reporting, and operational and compliance auditing services to over ninety independent banks.</p><p> In 1998, she organized Thomas Consulting. At Thomas Consulting she now prepares bank plans, monthly financial reports, performs regulatory compliance audits and training and internal control audits for several banks. Additionally, she prepares and reviews Call Reports for several banks. Ms. Thomas has taught numerous call report seminars for state banking associations.</p><p> She has presented the Call Report Seminar to and has responded to questions from thousands of bankers in over 16 states. Her experience in working with a broad range of independent financial institutions is of unique value in understanding Call Report questions and in communicating with bankers in their language.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/annthomas.jpg ', N'https://ttseast.blob.core.windows.net/images/presenters/annthomas.jpg ')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10565, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/danasummer.jpg" alt="Photo of Dana Sumner" />Dana Sumner is a co-founder of Development Finance Training and Consulting, Inc. (DFTC), with more than 25 years of experience as a senior commercial lender and trainer. He has worked for several financial institutions in both the private and private non-profit sectors where he had the opportunity to be involved in all aspects of commercial lending. As a result, his approach to commercial lending issues is practical, hands-on, and based on real life situations.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/danasummer.jpg" alt="Photo of Dana Sumner" />Dana Sumner is a co-founder of Development Finance Training and Consulting, Inc. (DFTC), with more than 25 years of experience as a senior commercial lender and trainer. He has worked for several financial institutions in both the private and private non-profit sectors where he had the opportunity to be involved in all aspects of commercial lending. As a result, his approach to commercial lending issues is practical, hands-on, and based on real life situations.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/danasummer.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/danasummer.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10566, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/gregg.jpg" alt="Photo of Bob Gregg" />Bob Gregg, a partner at the Boardman &amp; Clark Law Firm in Madison, Wisconsin, has been involved in employment relations for more than 30 years. &nbsp;He litigates employment cases, representing employers in employment contracts, discrimination cases, FLSA, FMLA and all other areas of employment law. &nbsp;His main emphasis is helping employers achieve enhanced productivity. &nbsp;He has designed the workplace policies of numerous employers, creating positive work environments, and resolving employment problems before they generate lawsuits. &nbsp;Bob has conducted over 3,000 seminars throughout the United States and authored numerous articles on practical employment issues. &nbsp;Bob is a member of the Society for Human Resource Management, the National Speakers Association, is a National Faculty Member of the American Association for Affirmative Action and serves on the Board of Directors for the Department of Defense Equal Opportunity Management Institute Foundation.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/gregg.jpg" alt="Photo of Bob Gregg" />Bob Gregg, a partner at the Boardman &amp; Clark Law Firm in Madison, Wisconsin, has been involved in employment relations for more than 30 years. &nbsp;He litigates employment cases, representing employers in employment contracts, discrimination cases, FLSA, FMLA and all other areas of employment law. &nbsp;His main emphasis is helping employers achieve enhanced productivity. &nbsp;He has designed the workplace policies of numerous employers, creating positive work environments, and resolving employment problems before they generate lawsuits. &nbsp;Bob has conducted over 3,000 seminars throughout the United States and authored numerous articles on practical employment issues. &nbsp;Bob is a member of the Society for Human Resource Management, the National Speakers Association, is a National Faculty Member of the American Association for Affirmative Action and serves on the Board of Directors for the Department of Defense Equal Opportunity Management Institute Foundation.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/gregg.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/gregg.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10567, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/mcguinn.jpg" alt="Photo of David P. McGuinn" />David P. McGuinn, President of Safe Deposit Specialists, is a former banker with 45 years of safe deposit experience and is often referred to nationwide as the safe deposit GURU. In all 50 states he has trained over 250,000 safe deposit personnel since 1969, and has served the industry as President of AIB and the American, Texas and Houston Safe Deposit Associations. Dave is a featured speaker for the American Bankers Associations TV network and has been interviewed by the Wall Street Journal, Banking-New York, Washington Post, Money Magazine, New York Magazine, Associated Press, AARP, National Public Radio, FDIC, CUNA, CNN, CBS, ABC, NBC Nightly News and Court TV on current safe deposit issues. McGuinn has created numerous training programs and his Safe Deposit Policy and Procedures Handbook, Regulatory/Compliance manual, products, brochures and training seminars are now the accepted standard for the financial industry.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/mcguinn.jpg" alt="Photo of David P. McGuinn" />David P. McGuinn, President of Safe Deposit Specialists, is a former banker with 45 years of safe deposit experience and is often referred to nationwide as the safe deposit GURU. In all 50 states he has trained over 250,000 safe deposit personnel since 1969, and has served the industry as President of AIB and the American, Texas and Houston Safe Deposit Associations. Dave is a featured speaker for the American Bankers Associations TV network and has been interviewed by the Wall Street Journal, Banking-New York, Washington Post, Money Magazine, New York Magazine, Associated Press, AARP, National Public Radio, FDIC, CUNA, CNN, CBS, ABC, NBC Nightly News and Court TV on current safe deposit issues. McGuinn has created numerous training programs and his Safe Deposit Policy and Procedures Handbook, Regulatory/Compliance manual, products, brochures and training seminars are now the accepted standard for the financial industry.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/mcguinn.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/mcguinn.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10568, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/crawford.jpg" alt="Photo of Deborah Crawford" />Deborah Crawford is the President of gettechnical inc. She specializes in compliance and regulations for the deposit side of financial institutions.  Her 20+ year career in banking and training began at Hibernia National Bank. She has been a seminar leader for many state associations and credit union groups across the nation.  She has Bachelors and Masters degrees from Louisiana State University. </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/crawford.jpg" alt="Photo of Deborah Crawford" />Deborah Crawford is the President of gettechnical inc. She specializes in compliance and regulations for the deposit side of financial institutions.  Her 20+ year career in banking and training began at Hibernia National Bank. She has been a seminar leader for many state associations and credit union groups across the nation.  She has Bachelors and Masters degrees from Louisiana State University. </p>', N'https://ttseast.blob.core.windows.net/images/presenters/crawford.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/crawford.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10569, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/Waldorf.jpg" alt="Photo of Douglas Waldorf" />Attorney Douglas L. Waldorf Jr., is a Florida Bar Board Certified Real Estate Lawyer whose practice focuses on banking industry clients. He represents lenders in commercial and residential loan transactions, as well as in mortgage foreclosures, deeds in lieu of foreclosure, forbearance agreements and other matters related to defaulted loan workouts. Prior to joining Henderson Franklin in August of 2003, he served for nearly twelve years as Vice President and Corporate Legal Counsel for SunTrust Bank.</p><p>Mr. Waldorf regularly serves as a lecturer on banking matters for the Miami-based Center for Financial Training. He writes The Lenders Perspective, a periodic newsletter for banking industry clients, and has also authored a book entitled Bank Loan Defaults: Strategies and Tactics for Lenders in Florida.</p><p>Mr. Waldorf was named to the 2006 list of Florida Super Lawyers which recognizes the states top five percent of attorneys as selected by extensive peer review.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/Waldorf.jpg" alt="Photo of Douglas Waldorf" />Attorney Douglas L. Waldorf Jr., is a Florida Bar Board Certified Real Estate Lawyer whose practice focuses on banking industry clients. He represents lenders in commercial and residential loan transactions, as well as in mortgage foreclosures, deeds in lieu of foreclosure, forbearance agreements and other matters related to defaulted loan workouts. Prior to joining Henderson Franklin in August of 2003, he served for nearly twelve years as Vice President and Corporate Legal Counsel for SunTrust Bank.</p><p>Mr. Waldorf regularly serves as a lecturer on banking matters for the Miami-based Center for Financial Training. He writes The Lenders Perspective, a periodic newsletter for banking industry clients, and has also authored a book entitled Bank Loan Defaults: Strategies and Tactics for Lenders in Florida.</p><p>Mr. Waldorf was named to the 2006 list of Florida Super Lawyers which recognizes the states top five percent of attorneys as selected by extensive peer review.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/waldorf.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/waldorf.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10570, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/iles.jpg" alt="Photo of Eileen Iles" />$Eileen Iles is an Executive in the Financial Institutions Risk Management group of Crowe Chizek, the eighth largest CPA and consulting company in the US. In this capacity, Eileen is responsible for the management and oversight of internal audit outsourcing services for financial institutions ranging in size from de novos to 10 billion, and developing Crowe Chizeks Risk Management continuing professional education program. Eileen has over 20 years of financial institutions experience, and prior to joining Crowe Chizek, she served as an adjunct Accounting faculty member at the University of New Mexico for five years. Eileen is a member of the Institute of Internal Auditors and Association of Certified Fraud Examiners. Eileen is also a CPA.', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/iles.jpg" alt="Photo of Eileen Iles" />$Eileen Iles is an Executive in the Financial Institutions Risk Management group of Crowe Chizek, the eighth largest CPA and consulting company in the US. In this capacity, Eileen is responsible for the management and oversight of internal audit outsourcing services for financial institutions ranging in size from de novos to 10 billion, and developing Crowe Chizeks Risk Management continuing professional education program. Eileen has over 20 years of financial institutions experience, and prior to joining Crowe Chizek, she served as an adjunct Accounting faculty member at the University of New Mexico for five years. Eileen is a member of the Institute of Internal Auditors and Association of Certified Fraud Examiners. Eileen is also a CPA.', N'https://ttseast.blob.core.windows.net/images/presenters/iles.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/iles.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10571, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/fast.jpg" alt="Photo of Elizabeth Fast" />$Elizabeth Fast, Esq. is a partner with Spencer Fane Britt &amp; Browne LLP where she specializes in the representation of financial institutions. She received her law degree from the University of Kansas and her undergraduate degree from Pittsburg State University. In addition, she has her Master of Business Administration degree and she is a Certified Public Accountant. Before joining Spencer Fane, she was the General Counsel, Senior Vice President and Corporate Secretary of a $9 billion bank with more than 130 branches, where she managed all legal, regulatory and compliance functions. She is a member of the Missouri State Banking Board, appointed by the Governor, and she is a member of the Kansas City Industrial Development Authority, appointed by the Mayor.', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/fast.jpg" alt="Photo of Elizabeth Fast" />$Elizabeth Fast, Esq. is a partner with Spencer Fane Britt &amp; Browne LLP where she specializes in the representation of financial institutions. She received her law degree from the University of Kansas and her undergraduate degree from Pittsburg State University. In addition, she has her Master of Business Administration degree and she is a Certified Public Accountant. Before joining Spencer Fane, she was the General Counsel, Senior Vice President and Corporate Secretary of a $9 billion bank with more than 130 branches, where she managed all legal, regulatory and compliance functions. She is a member of the Missouri State Banking Board, appointed by the Governor, and she is a member of the Kansas City Industrial Development Authority, appointed by the Mayor.', N'https://ttseast.blob.core.windows.net/images/presenters/fast.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/fast.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10572, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/north.jpg" alt="Photo of Eric North" /><IMG border=0 hspace=7" alt="" align=left src="http://www.bankwebinars.com/$webfile.send.WEBINARS./NORTH.GIF">Eric North has represented the interests of&nbsp;financial institutions&nbsp;as an attorney with respect to litigation, compliance, governance, bankruptcy and collections matters since 1984. Eric has appeared in state and federal courts throughout the State of California, and has argued before the Ninth Circuit Court of Appeal.</P><P>Eric is also a nationally recognized speaker on legal subjects affecting financial institutions, and has presented hundreds of programs for national, state and local credit union leagues and associations from around the country.</P>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/north.jpg" alt="Photo of Eric North" /><IMG border=0 hspace=7" alt="" align=left src="http://www.bankwebinars.com/$webfile.send.WEBINARS./NORTH.GIF">Eric North has represented the interests of&nbsp;financial institutions&nbsp;as an attorney with respect to litigation, compliance, governance, bankruptcy and collections matters since 1984. Eric has appeared in state and federal courts throughout the State of California, and has argued before the Ninth Circuit Court of Appeal.</P><P>Eric is also a nationally recognized speaker on legal subjects affecting financial institutions, and has presented hundreds of programs for national, state and local credit union leagues and associations from around the country.</P>', N'https://ttseast.blob.core.windows.net/images/presenters/north.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/north.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10573, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/foltz.jpg" alt="Photo of Gary Foltz" />$In a banking career spanning more than 30 years, Gary Foltz has held several management positions in the Operations and Treasury Management Departments of a large Midwestern financial institution. Most recently, he served as Senior Vice President, Cash Management/Electronic Transaction Services Group at UMB Bank, n.a., where his responsibilities included coordination of marketing, product profitability and new product development of EFT products and other services for UMB. Gary is a graduate of Pittsburg State University and has served as the lead faculty member of the Missouri School of Banking since its inception in 1986. Gary has also presented numerous American Institute of Banking (AIB) education seminars, and served as an instructor for AIB classroom and correspondence courses since 1979.', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/foltz.jpg" alt="Photo of Gary Foltz" />$In a banking career spanning more than 30 years, Gary Foltz has held several management positions in the Operations and Treasury Management Departments of a large Midwestern financial institution. Most recently, he served as Senior Vice President, Cash Management/Electronic Transaction Services Group at UMB Bank, n.a., where his responsibilities included coordination of marketing, product profitability and new product development of EFT products and other services for UMB. Gary is a graduate of Pittsburg State University and has served as the lead faculty member of the Missouri School of Banking since its inception in 1986. Gary has also presented numerous American Institute of Banking (AIB) education seminars, and served as an instructor for AIB classroom and correspondence courses since 1979.', N'https://ttseast.blob.core.windows.net/images/presenters/foltz.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/foltz.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10574, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/souther.jpg" alt="Photo of Greg Souther" />Greg Souther is President of Greg Souther Consulting &amp; Seminars (www.gregsouther.com) a firm that provides training and consulting to Financial Institutions in the following areas: Customer Service &amp; Communication; Credit, Collection, &amp; Compliance; Fraud Prevention &amp; Information Security; and Marketing &amp; Sales.</p><p>With over 28 years of training and speaking experience, Greg and his associates share practical "how to" advice that everyone can easily understand and use in their daily work environment.</p><p>Greg was Co-Owner and Manager of The Credit Bureaus of Southeast Georgia, the parent company for six Credit Reporting and Collection Agencies based in Brunswick, Georgia.  Other Management, Marketing, and Human Resource experience includes Credifax, formerly the Credit Bureau of Jacksonville, the Credit Bureau of Valdosta, and the Credit Bureau of Athens.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/souther.jpg" alt="Photo of Greg Souther" />Greg Souther is President of Greg Souther Consulting &amp; Seminars (www.gregsouther.com) a firm that provides training and consulting to Financial Institutions in the following areas: Customer Service &amp; Communication; Credit, Collection, &amp; Compliance; Fraud Prevention &amp; Information Security; and Marketing &amp; Sales.</p><p>With over 28 years of training and speaking experience, Greg and his associates share practical "how to" advice that everyone can easily understand and use in their daily work environment.</p><p>Greg was Co-Owner and Manager of The Credit Bureaus of Southeast Georgia, the parent company for six Credit Reporting and Collection Agencies based in Brunswick, Georgia.  Other Management, Marketing, and Human Resource experience includes Credifax, formerly the Credit Bureau of Jacksonville, the Credit Bureau of Valdosta, and the Credit Bureau of Athens.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/souther.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/souther.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10577, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/turner.jpg" alt="Photo of J.T. Turner" />The webinar leader is J.T. Turner, who has over 28 years of experience in the lending industry. He has worked as a trainer for the past 22 years, in areas of lending, underwriting, origination, quality control, and personal growth. He is a seminar leader for the Center for Financial Training, a member of the Franklin Speakers Bureau, and past member of the National Speakers Association. J.T. is also a professional actor, with credits in film, TV, radio and on the stage. </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/turner.jpg" alt="Photo of J.T. Turner" />The webinar leader is J.T. Turner, who has over 28 years of experience in the lending industry. He has worked as a trainer for the past 22 years, in areas of lending, underwriting, origination, quality control, and personal growth. He is a seminar leader for the Center for Financial Training, a member of the Franklin Speakers Bureau, and past member of the National Speakers Association. J.T. is also a professional actor, with credits in film, TV, radio and on the stage. </p>', N'https://ttseast.blob.core.windows.net/images/presenters/turner.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/turner.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10578, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/branch.jpg" alt="Photo of Janice Branch" />Janice Branch has been a senior training consultant for InterAction Training for twenty years. She is a very seasoned presenter that has all the right stuff to wow her participants about the subject matter. Prior to joining InterAction Training, Janice was the Senior Manager of Training for Consolidated Communications where she managed, designed, coordinated and presented training programs for this multi-state telecommunications company with over 1000 employees.</p><p>Whether it is teaching how to coach, manage, lead, negotiate, service, sell or train at every level in an organization or if it is consulting on problem solving and servant leadership, Janice is the "go-to" person every bank wants to hear from. Participants appreciate her "been there, done that" humor along with her expert ability to facilitate learning.</p><p>Janice has obtained a Bachelor of Business Administration with a major in Management from Almeda University and is certified by the University of Houston in Leadership and Management. In addition, Janice has obtained trainer certifications from Achieve Global and Development Dimensions, Inc.</p><p>A native Texan she enjoys many pursuits in addition to teaching and learning but none more than being a grandmother and tending to her ten acre home in Montgomery, Texas just north of Houston.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/branch.jpg" alt="Photo of Janice Branch" />Janice Branch has been a senior training consultant for InterAction Training for twenty years. She is a very seasoned presenter that has all the right stuff to wow her participants about the subject matter. Prior to joining InterAction Training, Janice was the Senior Manager of Training for Consolidated Communications where she managed, designed, coordinated and presented training programs for this multi-state telecommunications company with over 1000 employees.</p><p>Whether it is teaching how to coach, manage, lead, negotiate, service, sell or train at every level in an organization or if it is consulting on problem solving and servant leadership, Janice is the "go-to" person every bank wants to hear from. Participants appreciate her "been there, done that" humor along with her expert ability to facilitate learning.</p><p>Janice has obtained a Bachelor of Business Administration with a major in Management from Almeda University and is certified by the University of Houston in Leadership and Management. In addition, Janice has obtained trainer certifications from Achieve Global and Development Dimensions, Inc.</p><p>A native Texan she enjoys many pursuits in addition to teaching and learning but none more than being a grandmother and tending to her ten acre home in Montgomery, Texas just north of Houston.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/branch.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/branch.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10581, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/wehrmeyer.jpg" alt="Photo of Jeni Wehrmeyer" />Jeni Wehrmeyer is the Chief Marketing Officer for Anthony Cole Training Group (ACTG), a Cincinnati-based and national sales development firm. ACTG has been working with financial firms for 15 years concerning their sales, sales management, recruiting and leadership issues. Jeni’s prior background includes more than 12 years as VP of Marketing at Fifth Third Bank and in that role, she handled all aspects of marketing including lead generation, training, advertising, sales support, etc. Throughout her career, Jeni has always been in sales or sales support roles.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/wehrmeyer.jpg" alt="Photo of Jeni Wehrmeyer" />Jeni Wehrmeyer is the Chief Marketing Officer for Anthony Cole Training Group (ACTG), a Cincinnati-based and national sales development firm. ACTG has been working with financial firms for 15 years concerning their sales, sales management, recruiting and leadership issues. Jeni’s prior background includes more than 12 years as VP of Marketing at Fifth Third Bank and in that role, she handled all aspects of marketing including lead generation, training, advertising, sales support, etc. Throughout her career, Jeni has always been in sales or sales support roles.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/wehrmeyer.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/wehrmeyer.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10582, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/burke.jpg" alt="Photo of Jennifer Burke" />Jennifer Frazier Burke, CPA, CRP,  is currently the executive in charge of the Outsourcing Internal Audit Services group for Crowe Chizek, one of the 10 largest CPA and consulting companies in the US.  In this capacity, Jennifer is responsible for the management and oversight of internal audit outsourcing services for over 300 financial institutions ranging in size from de novos to 6+ billion, and a staff of over 40 internal audit specialists.  She also provides thought leadership in the development, sales and delivery of the risk-based internal audit outsourcing approach for Crowe Chizek.  Jennifer has over 13 years of internal audit experience, and prior to joining Crowe Chizek, she previously served as Senior Vice President and Corporate General Auditor at a $1.7 billion bank holding company.  </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/burke.jpg" alt="Photo of Jennifer Burke" />Jennifer Frazier Burke, CPA, CRP,  is currently the executive in charge of the Outsourcing Internal Audit Services group for Crowe Chizek, one of the 10 largest CPA and consulting companies in the US.  In this capacity, Jennifer is responsible for the management and oversight of internal audit outsourcing services for over 300 financial institutions ranging in size from de novos to 6+ billion, and a staff of over 40 internal audit specialists.  She also provides thought leadership in the development, sales and delivery of the risk-based internal audit outsourcing approach for Crowe Chizek.  Jennifer has over 13 years of internal audit experience, and prior to joining Crowe Chizek, she previously served as Senior Vice President and Corporate General Auditor at a $1.7 billion bank holding company.  </p>', N'https://ttseast.blob.core.windows.net/images/presenters/burke.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/burke.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10583, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/rechel.jpg" alt="Photo of Jim Rechel" />Jim is president of The Rechel Group, Inc., a risk-consulting firm headquartered in Cincinnati, Ohio. He is on the board of The Institute for Criminal Justice Education, Montgomery, Alabama and a member of numerous national organizations, and is a Certified Financial Security Officer. He is a past local board member of the International Association of Financial Crimes Investigators and the American Society of Industrial Security.</p><p>Prior to working for The Rechel Group, Inc, Jim was vice president for Fifth Third Bank headquartered in Cincinnati, where he held positions in various departments, including Retail and Lending, and Security Director and was an Special Agent with the FBI.</p><p>His presentations are both energetic and informative, with practical applications and solutions for business professionals. His work has been highlighted in both local and national publications, including CEO Magazine, Security Director Digest, Cincinnati Enquirer, USA Today, and CNBC.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/rechel.jpg" alt="Photo of Jim Rechel" />Jim is president of The Rechel Group, Inc., a risk-consulting firm headquartered in Cincinnati, Ohio. He is on the board of The Institute for Criminal Justice Education, Montgomery, Alabama and a member of numerous national organizations, and is a Certified Financial Security Officer. He is a past local board member of the International Association of Financial Crimes Investigators and the American Society of Industrial Security.</p><p>Prior to working for The Rechel Group, Inc, Jim was vice president for Fifth Third Bank headquartered in Cincinnati, where he held positions in various departments, including Retail and Lending, and Security Director and was an Special Agent with the FBI.</p><p>His presentations are both energetic and informative, with practical applications and solutions for business professionals. His work has been highlighted in both local and national publications, including CEO Magazine, Security Director Digest, Cincinnati Enquirer, USA Today, and CNBC.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/rechel.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/rechel.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10584, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/barrickman.jpg" alt="Photo of John Barrickman" /><p>John Barrickman has extensive experience in all aspects of banking including retail banking, commercial lending, credit administration and credit training. He also served for five years as president and chief executive officer of a $185 million financial institution.</p><p>In addition, Mr. Barrickman has been a bank consultant focusing on risk management, credit process, strategic planning, and all aspects of commercial lending.</p><p>Mr. Barrickman has also been active in banker education serving on the faculty of a number of regional lending schools and graduate schools of banking. He has also authored curricula on commercial lending for use in commercial lending schools. Mr. Barrickman has co-authored a book entitled Strategic Credit Risk Management for Robert Morris Associates. </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/barrickman.jpg" alt="Photo of John Barrickman" /><p>John Barrickman has extensive experience in all aspects of banking including retail banking, commercial lending, credit administration and credit training. He also served for five years as president and chief executive officer of a $185 million financial institution.</p><p>In addition, Mr. Barrickman has been a bank consultant focusing on risk management, credit process, strategic planning, and all aspects of commercial lending.</p><p>Mr. Barrickman has also been active in banker education serving on the faculty of a number of regional lending schools and graduate schools of banking. He has also authored curricula on commercial lending for use in commercial lending schools. Mr. Barrickman has co-authored a book entitled Strategic Credit Risk Management for Robert Morris Associates. </p>', N'https://ttseast.blob.core.windows.net/images/presenters/barrickman.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/barrickman.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10585, N'<P><IMG alt="" hspace=0 src="http://www.bankwebinars.com/$webfile.send.WEBINARS./OLIVER.JPG" align=baseline border=0></P><P>John Olivers career in the financial services industry spans over thirty five years, working both in Europe and the United States. For the past eighteen years, in addition to his role as a banker, he has built a thriving consulting practice with focus on strategic planning and the developmental needs of managers and directors in the financial services industry. </P><P>Through his company, Laurel Management Systems, Inc., Mr. Oliver specializes in strategic management consulting and in the design, development, and implementation of instructor-led training programs. Some of these programs are structured around sophisticated computer simulations of the industry. He is responsible for the design and implementation of his company’s highly regarded FIplanner strategic planning process. As a result of his extensive management development training experience he has a', N'<P><IMG alt="" hspace=0 src="http://www.bankwebinars.com/$webfile.send.WEBINARS./OLIVER.JPG" align=baseline border=0></P><P>John Olivers career in the financial services industry spans over thirty five years, working both in Europe and the United States. For the past eighteen years, in addition to his role as a banker, he has built a thriving consulting practice with focus on strategic planning and the developmental needs of managers and directors in the financial services industry. </P><P>Through his company, Laurel Management Systems, Inc., Mr. Oliver specializes in strategic management consulting and in the design, development, and implementation of instructor-led training programs. Some of these programs are structured around sophisticated computer simulations of the industry. He is responsible for the design and implementation of his company’s highly regarded FIplanner strategic planning process. As a result of his extensive management development training experience he has a', N'https://ttseast.blob.core.windows.net/images/presenters/oliver.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/oliver.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10586, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/nelson.jpg" alt="Photo of Karl Nelson" />Karl Nelson is the President and CEO of KPN Consulting, an organization engaged in the ALCO, Funding, and Liquidity arena. His career has included positions as Director of Industry and Governmental Relations with Silverton Bank, President and Chief Marketing Officer of Institutional Deposits Corp (SR), and National Market Development Director for Promontory Interfinancial Network where he worked on national marketing strategies for the CDARS program. </p>  <p>In addition, Karl served as a Senior Vice President with the Federal Home Loan Bank of Atlanta from 1991 through 2002 where he managed the sales and marketing, strategic planning, and trade association/regulatory outreach efforts and served on the banks ALCO. Prior to joining the Home Loan Bank, he was involved for eighteen years with various regional banks including Barnett, Florida National, AmeriTrust Company, Society National Bank, and FNB Atlanta. Karl began his banking career with Chase Manhattan Bank in 1972.</p>  <p>Karl is a popular speaker on such topics as Funding, Liquidity, Contingency Funding Plans, the ALCO Process, and ROE Enhancement and over the past 3 1/2 years, he has provided 155 workshops to over 6,000 participants. </p>  <p>Karl serves on the faculties of the Graduate School of Banking in Madison, Wisconsin and Boulder, Colorado, the Graduate School of Bank Investments & Financial Management in Columbia, South Carolina, the Financial Managers School in Madison, the Asian Banking Academy, as well as the faculties of the state banking schools in Florida, North Carolina, and Tennessee. Mr. Nelson is an organizing Director and ALCO Chair for a de novo bank in North Carolina.</p> ', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/nelson.jpg" alt="Photo of Karl Nelson" />Karl Nelson is the President and CEO of KPN Consulting, an organization engaged in the ALCO, Funding, and Liquidity arena. His career has included positions as Director of Industry and Governmental Relations with Silverton Bank, President and Chief Marketing Officer of Institutional Deposits Corp (SR), and National Market Development Director for Promontory Interfinancial Network where he worked on national marketing strategies for the CDARS program. </p>  <p>In addition, Karl served as a Senior Vice President with the Federal Home Loan Bank of Atlanta from 1991 through 2002 where he managed the sales and marketing, strategic planning, and trade association/regulatory outreach efforts and served on the banks ALCO. Prior to joining the Home Loan Bank, he was involved for eighteen years with various regional banks including Barnett, Florida National, AmeriTrust Company, Society National Bank, and FNB Atlanta. Karl began his banking career with Chase Manhattan Bank in 1972.</p>  <p>Karl is a popular speaker on such topics as Funding, Liquidity, Contingency Funding Plans, the ALCO Process, and ROE Enhancement and over the past 3 1/2 years, he has provided 155 workshops to over 6,000 participants. </p>  <p>Karl serves on the faculties of the Graduate School of Banking in Madison, Wisconsin and Boulder, Colorado, the Graduate School of Bank Investments & Financial Management in Columbia, South Carolina, the Financial Managers School in Madison, the Asian Banking Academy, as well as the faculties of the state banking schools in Florida, North Carolina, and Tennessee. Mr. Nelson is an organizing Director and ALCO Chair for a de novo bank in North Carolina.</p> ', N'https://ttseast.blob.core.windows.net/images/presenters/nelson.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/nelson.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10587, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/reed.jpg" alt="Photo of Kathy Reed" />Kathy Reed has over 17 years of leadership experience increasing bank performance and profits. She leads a consulting practice whose mission is to improve profitability and reduce risk. Kathy has achieved recognition for her ability to quickly identify and diagnose organizational and process weaknesses and develop innovative solutions. A certified Business Process Manager, Kathy was instrumental in helping a major bank realize record performance levels through her leadership of a multi-year re-engineering program. A former FDIC commissioned bank examiner, she lead examinations of financial institutions to determine their financial health and viability.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/reed.jpg" alt="Photo of Kathy Reed" />Kathy Reed has over 17 years of leadership experience increasing bank performance and profits. She leads a consulting practice whose mission is to improve profitability and reduce risk. Kathy has achieved recognition for her ability to quickly identify and diagnose organizational and process weaknesses and develop innovative solutions. A certified Business Process Manager, Kathy was instrumental in helping a major bank realize record performance levels through her leadership of a multi-year re-engineering program. A former FDIC commissioned bank examiner, she lead examinations of financial institutions to determine their financial health and viability.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/reed.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/reed.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10590, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/demarino.jpg" alt="Photo of Margaret DeMarino" />Margaret DeMarino is a corporate trainer, specializing in the area of written and verbal communication, supervisory skills, administrative training, and customer service. Known for her functional webinars and workshops filled with practical pointers, Ms. DeMarino offers workshops and webinars to a wide range of clients including, banks and financial institutions, manufacturing companies, state and federal government agencies, and others.  Ms. DeMarino  holds a B.A. in Communication Arts from the University of Dayton and was a Fellow of the Yale-New Haven Teachers Institute at Yale University. She also currently free-lances for the Hartford Courant.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/demarino.jpg" alt="Photo of Margaret DeMarino" />Margaret DeMarino is a corporate trainer, specializing in the area of written and verbal communication, supervisory skills, administrative training, and customer service. Known for her functional webinars and workshops filled with practical pointers, Ms. DeMarino offers workshops and webinars to a wide range of clients including, banks and financial institutions, manufacturing companies, state and federal government agencies, and others.  Ms. DeMarino  holds a B.A. in Communication Arts from the University of Dayton and was a Fellow of the Yale-New Haven Teachers Institute at Yale University. She also currently free-lances for the Hartford Courant.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/demarino.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/demarino.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10591, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/trinkle.jpg" alt="Photo of Mark Trinkle" />Mark Trinkle has more than 15 years experience at a Midwest insurance and banking firm where he was in sales and sales management. He brings that ‘hands on’ mentality with him in his role as a Sales Development Expert at ACTG. Mark has found his calling as a sales and management trainer. His clients and webinar participants are easily won over by his personal warmth, sense of humor and ability to engage and coach. He tries to live by one of his favorite quotes by Aristotle, ‘We are what we repeatedly do. Excellence, therefore, is not an act but a habit. </P>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/trinkle.jpg" alt="Photo of Mark Trinkle" />Mark Trinkle has more than 15 years experience at a Midwest insurance and banking firm where he was in sales and sales management. He brings that ‘hands on’ mentality with him in his role as a Sales Development Expert at ACTG. Mark has found his calling as a sales and management trainer. His clients and webinar participants are easily won over by his personal warmth, sense of humor and ability to engage and coach. He tries to live by one of his favorite quotes by Aristotle, ‘We are what we repeatedly do. Excellence, therefore, is not an act but a habit. </P>', N'https://ttseast.blob.core.windows.net/images/presenters/trinkle.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/trinkle.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10592, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/tyrpin.jpg" alt="Photo of Mark Tyrpin" />$Mark Tyrpin is a senior vice-president for a large Midwestern Community Bank.&nbsp; He has over 18 years of banking experience including commercial lending, commercial real estate lending, and loan rehabilitation and workouts.&nbsp; Prior to that, Mark was an investment banker for five years, specializing in municipal finance and trading.&nbsp; Mark teaches economics classes at area community colleges and conducts seminars on lending throughout the Midwest.', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/tyrpin.jpg" alt="Photo of Mark Tyrpin" />$Mark Tyrpin is a senior vice-president for a large Midwestern Community Bank.&nbsp; He has over 18 years of banking experience including commercial lending, commercial real estate lending, and loan rehabilitation and workouts.&nbsp; Prior to that, Mark was an investment banker for five years, specializing in municipal finance and trading.&nbsp; Mark teaches economics classes at area community colleges and conducts seminars on lending throughout the Midwest.', N'https://ttseast.blob.core.windows.net/images/presenters/tyrpin.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/tyrpin.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10595, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/percy.jpg" alt="Photo of Michael Percy" />$Mike Percy is the Executive in Charge of Crowe Chizeks Financial Institution Group in Florida.  In this role, he oversees the services provided to more than 60 financial institutions throughout Florida.  Mike has 20 years of experience serving financial institutions from denovo banks to large holding companies with assets in excess of $18 Billion.  Throughout his career, Mike has focused his efforts on the financial institution industry.', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/percy.jpg" alt="Photo of Michael Percy" />$Mike Percy is the Executive in Charge of Crowe Chizeks Financial Institution Group in Florida.  In this role, he oversees the services provided to more than 60 financial institutions throughout Florida.  Mike has 20 years of experience serving financial institutions from denovo banks to large holding companies with assets in excess of $18 Billion.  Throughout his career, Mike has focused his efforts on the financial institution industry.', N'https://ttseast.blob.core.windows.net/images/presenters/percy.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/percy.jpg')
GO
