INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10598, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/cashman.jpg" alt="Photo of Patricia Cashman" />Patricia Cashman is the owner of Cashman Compliance Solutions, a company that provides compliance reviews, training and support to community financial institutions. She has been the senior operations officer for three Dallas-Ft. Worth area community banks, an assistant examiner for the Texas Department of Banking and managed the compliance/internal audit division of TIB – The Independent BankersBank, one of the largest bankers’ banks in the country.  </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/cashman.jpg" alt="Photo of Patricia Cashman" />Patricia Cashman is the owner of Cashman Compliance Solutions, a company that provides compliance reviews, training and support to community financial institutions. She has been the senior operations officer for three Dallas-Ft. Worth area community banks, an assistant examiner for the Texas Department of Banking and managed the compliance/internal audit division of TIB – The Independent BankersBank, one of the largest bankers’ banks in the country.  </p>', N'https://ttseast.blob.core.windows.net/images/presenters/cashman.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/cashman.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10599, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/bruno.jpg" alt="Photo of Phil Bruno" />$Phil Bruno, professional speaker, trainer and consultant, works with organizations to enhance their customers total experience and increase sales and bottom line profits. He began his professional career in Corporate America looking for ways to meet the needs of his own organization, Anheuser-Busch, but his appreciation for good customer service began long before then.', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/bruno.jpg" alt="Photo of Phil Bruno" />$Phil Bruno, professional speaker, trainer and consultant, works with organizations to enhance their customers total experience and increase sales and bottom line profits. He began his professional career in Corporate America looking for ways to meet the needs of his own organization, Anheuser-Busch, but his appreciation for good customer service began long before then.', N'https://ttseast.blob.core.windows.net/images/presenters/bruno.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/bruno.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10600, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/adler.jpg" alt="Photo of Ray Adler" />Ray Adler is President, CEO and Founder of BTI</p><p>Ray is a nationally recognized author, speaker and expert in the field of building sales cultures, sales strategies and sales processes exclusively in the banking industry. Since founding BTI in 1999, BTI has worked with banks in ten States. Ray Adler has been one of CFT Western States most sought after presenters for the past four years.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/adler.jpg" alt="Photo of Ray Adler" />Ray Adler is President, CEO and Founder of BTI</p><p>Ray is a nationally recognized author, speaker and expert in the field of building sales cultures, sales strategies and sales processes exclusively in the banking industry. Since founding BTI in 1999, BTI has worked with banks in ten States. Ray Adler has been one of CFT Western States most sought after presenters for the past four years.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/adler.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/adler.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10601, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/peterson.jpg" alt="Photo of Richard Peterson" />$Richard Peterson,  a former bank president who combines 17 years of banking experience with extensive teaching credentials.  He conducts hundreds of seminars annually, and has also conducted classes for the American Management Association and the School of Bank Marketing at the University of Colorado. ', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/peterson.jpg" alt="Photo of Richard Peterson" />$Richard Peterson,  a former bank president who combines 17 years of banking experience with extensive teaching credentials.  He conducts hundreds of seminars annually, and has also conducted classes for the American Management Association and the School of Bank Marketing at the University of Colorado. ', N'https://ttseast.blob.core.windows.net/images/presenters/peterson.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/peterson.jpg')
