INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10602, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/morin.jpg" alt="Photo of Roger Morin" />Roger Morin is President of Morin & Associates USA, one of Americas leading training and consulting firms for the financial services industry. A former international banker for the First National Bank of Chicago, Roger also worked as a director of human resources for a multi branch community bank on Chicagos north side neighborhood. </p><p>Roger is senior faculty at the Keller Graduate School of Management MBA program at DeVry University in Chicago, Illinois. Roger brings a wide range of business experience. He was a Director of Human Resources for the Marriott Corporation and Midwest Human Resources Manager for Burlington Air Express.</p><p>Roger has addressed executives at the McDonalds Corporate Headquarters in Oak Brook, Illinois, the United States Post Office in Chicago, the University of Chicago Hospital, Commonwealth Edison Company, and the National Opinion Research Center.</p><p>Recently Roger addressed financial services leaders at, the Florida Bankers Association, the Michigan Bankers Association, the Virginia Bankers Association, the Ohio Bankers League, and hundreds of bankers throughout the U.S and abroad.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/morin.jpg" alt="Photo of Roger Morin" />Roger Morin is President of Morin & Associates USA, one of Americas leading training and consulting firms for the financial services industry. A former international banker for the First National Bank of Chicago, Roger also worked as a director of human resources for a multi branch community bank on Chicagos north side neighborhood. </p><p>Roger is senior faculty at the Keller Graduate School of Management MBA program at DeVry University in Chicago, Illinois. Roger brings a wide range of business experience. He was a Director of Human Resources for the Marriott Corporation and Midwest Human Resources Manager for Burlington Air Express.</p><p>Roger has addressed executives at the McDonalds Corporate Headquarters in Oak Brook, Illinois, the United States Post Office in Chicago, the University of Chicago Hospital, Commonwealth Edison Company, and the National Opinion Research Center.</p><p>Recently Roger addressed financial services leaders at, the Florida Bankers Association, the Michigan Bankers Association, the Virginia Bankers Association, the Ohio Bankers League, and hundreds of bankers throughout the U.S and abroad.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/morin.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/morin.jpg')
GO
