INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10604, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/becker.jpg" alt="Photo of Scott Becker" />Scott Becker, Esq. is a licensed practicing attorney in Lakeville, Minnesota.  He has taught a variety of classes on and concentrates much of his practice on employee benefits, corporate work, and retirement planning.  His interactive style with practical answers makes him a favorite for attendees of his seminars.  </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/becker.jpg" alt="Photo of Scott Becker" />Scott Becker, Esq. is a licensed practicing attorney in Lakeville, Minnesota.  He has taught a variety of classes on and concentrates much of his practice on employee benefits, corporate work, and retirement planning.  His interactive style with practical answers makes him a favorite for attendees of his seminars.  </p>', N'https://ttseast.blob.core.windows.net/images/presenters/becker.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/becker.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10605, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/fink.jpg" alt="Photo of Scott Fink" />Scott D. Fink is an associate focused on bankruptcy at Weltman, Weinberg & Reis Co., L.P.A. who has represented creditors on hundreds of bankruptcies across the nation. He earned his JD from Case Western Reserve University School of Law in 1997 and his BA in Political Science from Miami University in 1993. A member of the Ohio State and Cuyahoga-Cleveland Metropolitan Bar Associations, Scott is licensed in Ohio. He is admitted to practice before the US District Court (Northern & Southern Districts of OH) and has successfully argued before the US Court of Appeals for the Sixth Circuit. Scott was recently named an Ohio Rising Star by Ohio Super Lawyer Magazine for 2010, and is a frequent lecturer on bankruptcy law and creditors rights issues. </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/fink.jpg" alt="Photo of Scott Fink" />Scott D. Fink is an associate focused on bankruptcy at Weltman, Weinberg & Reis Co., L.P.A. who has represented creditors on hundreds of bankruptcies across the nation. He earned his JD from Case Western Reserve University School of Law in 1997 and his BA in Political Science from Miami University in 1993. A member of the Ohio State and Cuyahoga-Cleveland Metropolitan Bar Associations, Scott is licensed in Ohio. He is admitted to practice before the US District Court (Northern & Southern Districts of OH) and has successfully argued before the US Court of Appeals for the Sixth Circuit. Scott was recently named an Ohio Rising Star by Ohio Super Lawyer Magazine for 2010, and is a frequent lecturer on bankruptcy law and creditors rights issues. </p>', N'https://ttseast.blob.core.windows.net/images/presenters/fink.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/fink.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10606, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/lange.jpg" alt="Photo of Stan Lange" />Stan Lange is a supervisor of trainers for New Horizons Computer Learning. He has a strong background in education at all levels with over 40 years’ experience in teaching middle school, high school, and adult students. At New Horizons he teaches primarily the Microsoft Office suite (Word, PowerPoint, Excel, Project, Outlook, Publisher, Access, and FrontPage). He also teaches Crystal Reports, Adobe products, and professional business classes (Business Writing, Resume Construction, Interviewing, and Project Management). Stan holds a Bachelor of Science degree in Secondary Education. </P>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/lange.jpg" alt="Photo of Stan Lange" />Stan Lange is a supervisor of trainers for New Horizons Computer Learning. He has a strong background in education at all levels with over 40 years’ experience in teaching middle school, high school, and adult students. At New Horizons he teaches primarily the Microsoft Office suite (Word, PowerPoint, Excel, Project, Outlook, Publisher, Access, and FrontPage). He also teaches Crystal Reports, Adobe products, and professional business classes (Business Writing, Resume Construction, Interviewing, and Project Management). Stan holds a Bachelor of Science degree in Secondary Education. </P>', N'https://ttseast.blob.core.windows.net/images/presenters/lange.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/lange.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10607, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/orr.jpg" alt="Photo of Susan Orr" />Susan Orr is a leading financial services expert with vast regulatory, risk management, and security best practice knowledge and expertise.</p><p>As an auditor and consultant, Susan is dedicated to assisting financial institutions in implementing appropriate policies and controls to protect confidential information and comply with regulatory mandates and best practices. Her expertise as an auditor and former examiner provides her the knowledge and expertise to conduct comprehensive IT general control and data security reviews and assist de novo institutions in the vendor selection process, preparing policies and procedures, and instituting controls. She also consults for numerous security providers and vendors helping them align products and services to meet institution regulatory mandates. Susan is a Certified Information Systems Auditor (CISA), Certified Information Security Manager (CISM), Certified in Risk and Information Systems Control (CRISC), and Certified Risk Professional (CRP).</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/orr.jpg" alt="Photo of Susan Orr" />Susan Orr is a leading financial services expert with vast regulatory, risk management, and security best practice knowledge and expertise.</p><p>As an auditor and consultant, Susan is dedicated to assisting financial institutions in implementing appropriate policies and controls to protect confidential information and comply with regulatory mandates and best practices. Her expertise as an auditor and former examiner provides her the knowledge and expertise to conduct comprehensive IT general control and data security reviews and assist de novo institutions in the vendor selection process, preparing policies and procedures, and instituting controls. She also consults for numerous security providers and vendors helping them align products and services to meet institution regulatory mandates. Susan is a Certified Information Systems Auditor (CISA), Certified Information Security Manager (CISM), Certified in Risk and Information Systems Control (CRISC), and Certified Risk Professional (CRP).</p>', N'https://ttseast.blob.core.windows.net/images/presenters/orr.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/orr.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10608, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/allen.jpg" alt="Photo of Teresa Allen" />Teresa Allen works with financial institutions who want to improve sales and customer service performance in order to build success and grow profits. Teresa is owner of Common Sense Solutions, a national training and consulting firm. She is a member of the National Speakers Association and past recipient of the ASTD Professional Trainer of the Year Award. Teresa has presented to the financial industry for over fifteen years at local, state and national meetings. She is author of Common Sense Service: Close Encounters on the Front Lines and is co-author of The Service Path: Your Roadmap for Building Strong Customer Loyalty. Teresa is a graduate of Miami University in Oxford, Ohio where she earned her B.S. in Business Administration with a degree in Marketing. </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/allen.jpg" alt="Photo of Teresa Allen" />Teresa Allen works with financial institutions who want to improve sales and customer service performance in order to build success and grow profits. Teresa is owner of Common Sense Solutions, a national training and consulting firm. She is a member of the National Speakers Association and past recipient of the ASTD Professional Trainer of the Year Award. Teresa has presented to the financial industry for over fifteen years at local, state and national meetings. She is author of Common Sense Service: Close Encounters on the Front Lines and is co-author of The Service Path: Your Roadmap for Building Strong Customer Loyalty. Teresa is a graduate of Miami University in Oxford, Ohio where she earned her B.S. in Business Administration with a degree in Marketing. </p>', N'https://ttseast.blob.core.windows.net/images/presenters/allen.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/allen.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (10609, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/tthomas.jpg " alt="Photo of Terri D. Thomas" />Terri D. Thomas is Senior VP and Legal Department Director for the Kansas Bankers Association. Prior to this, she was with "Bankers Choice," a financial consulting firm. Before this, Terri was employed in the financial industry for over twenty-three years in various capacities. Most notably, she served for fourteen years as in-house legal counsel and trust officer for Bank of America and its Kansas predecessors. Receiving her Bachelor of Arts degree from Kansas State University in 1985, Terri continued her education at Washburn University School of Law and obtained her Juris Doctor in 1988.</p><p> Presently, she serves as an adjunct instructor at Washburn University School of Law and the University of Kansas School of Law and is a frequent seminar presenter for financial associations.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/tthomas.jpg " alt="Photo of Terri D. Thomas" />Terri D. Thomas is Senior VP and Legal Department Director for the Kansas Bankers Association. Prior to this, she was with "Bankers Choice," a financial consulting firm. Before this, Terri was employed in the financial industry for over twenty-three years in various capacities. Most notably, she served for fourteen years as in-house legal counsel and trust officer for Bank of America and its Kansas predecessors. Receiving her Bachelor of Arts degree from Kansas State University in 1985, Terri continued her education at Washburn University School of Law and obtained her Juris Doctor in 1988.</p><p> Presently, she serves as an adjunct instructor at Washburn University School of Law and the University of Kansas School of Law and is a frequent seminar presenter for financial associations.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/tthomas.jpg ', N'https://ttseast.blob.core.windows.net/images/presenters/tthomas.jpg ')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (11114, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/flynn.jpg" alt="Photo of Nancy Flynn" />A recognized expert on workplace e-mail policy, management and communications, Nancy Flynn is founder and executive director of The ePolicy Institute™. The ePolicy Institute is dedicated to helping employers limit e-mail risks, including litigation and regulatory investigations, through effective e-mail policies, training programs, and technology tools.<p>Nancy Flynn is the author of 10 books published in 7 languages, including The e-Policy Handbook, E-Mail Rules, Blog Rules, Instant Messaging Rules, E-Mail Management, and Writing Effective E-Mail.<p>Nancy Flynn is an in-demand speaker, trainer, and seminar leader with clients worldwide. She has conducted onsite and online training programs for banks, financial services firms, and other clients in North America, Europe, the Middle East, Asia, Australia, and the Caribbean. </p><p>She also serves as an expert witness for law firms and the federal government in e-mail-related litigation.<p>Since 2001, Nancy Flynn’s ePolicy Institute has collaborated with American Management Association on an annual survey of e-mail and Internet policies, procedures, and best practices.<p>A popular media source, Nancy Flynn been interviewed by thousands of media outlets including Fortune, Forbes, Time, NewsWeek, BusinessWeek, Wall Street Journal, US News & World Report, Financial Times, USA Today, Readers Digest, Independent Banker, New York Times, National Public Radio, CBS Early Show, ABC World News with Diane Sawyer, CNBC, CNN Anderson Cooper 360, and Fox Business News among others.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/flynn.jpg" alt="Photo of Nancy Flynn" />A recognized expert on workplace e-mail policy, management and communications, Nancy Flynn is founder and executive director of The ePolicy Institute™. The ePolicy Institute is dedicated to helping employers limit e-mail risks, including litigation and regulatory investigations, through effective e-mail policies, training programs, and technology tools.<p>Nancy Flynn is the author of 10 books published in 7 languages, including The e-Policy Handbook, E-Mail Rules, Blog Rules, Instant Messaging Rules, E-Mail Management, and Writing Effective E-Mail.<p>Nancy Flynn is an in-demand speaker, trainer, and seminar leader with clients worldwide. She has conducted onsite and online training programs for banks, financial services firms, and other clients in North America, Europe, the Middle East, Asia, Australia, and the Caribbean. </p><p>She also serves as an expert witness for law firms and the federal government in e-mail-related litigation.<p>Since 2001, Nancy Flynn’s ePolicy Institute has collaborated with American Management Association on an annual survey of e-mail and Internet policies, procedures, and best practices.<p>A popular media source, Nancy Flynn been interviewed by thousands of media outlets including Fortune, Forbes, Time, NewsWeek, BusinessWeek, Wall Street Journal, US News & World Report, Financial Times, USA Today, Readers Digest, Independent Banker, New York Times, National Public Radio, CBS Early Show, ABC World News with Diane Sawyer, CNBC, CNN Anderson Cooper 360, and Fox Business News among others.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/flynn.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/flynn.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (11158, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/lolley.jpg" alt="Photo of Anne Lolley" />For almost thirty years, Anne Lolley has been simplifying compliance issues for bankers. After earning her law degree from the University of Kansas, she joined the Kansas Bankers Association, where she developed its successful legal department and gave compliance-related seminars. She has been a compliance officer for two banks and currently works with Bank Management Services, where she continues to provide webinars to Kansas bankers. Her expertise at simplifying the complex and creating user-friendly reference manuals has made her a popular instructor.</P>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/lolley.jpg" alt="Photo of Anne Lolley" />For almost thirty years, Anne Lolley has been simplifying compliance issues for bankers. After earning her law degree from the University of Kansas, she joined the Kansas Bankers Association, where she developed its successful legal department and gave compliance-related seminars. She has been a compliance officer for two banks and currently works with Bank Management Services, where she continues to provide webinars to Kansas bankers. Her expertise at simplifying the complex and creating user-friendly reference manuals has made her a popular instructor.</P>', N'https://ttseast.blob.core.windows.net/images/presenters/lolley.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/lolley.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (12130, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/Vassallo.jpg" alt="Photo of Philip  Vassallo" />Philip Vassallo has designed, delivered, and supervised communication training programs for a wide range of executive, managerial, administrative and technical professionals in major multinational organizations for more than 30 years. He is the author of the books <span style="font-style: italic;">How to Write Fast Under Pressure</span>, <span style="font-style: italic;">The Art of E-Mail Writing</span>, and <span style="font-style: italic;">The Art of On-the-Job Writing</span>. He also writes the popular blog <span style="font-style: italic;">Words on the Line</span>, which offers practical tips for developing writers. Dr. Vassallo holds a B.A. in English, an M.S. in education, and a doctorate in educational theory.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/Vassallo.jpg" alt="Photo of Philip  Vassallo" />Philip Vassallo has designed, delivered, and supervised communication training programs for a wide range of executive, managerial, administrative and technical professionals in major multinational organizations for more than 30 years. He is the author of the books <span style="font-style: italic;">How to Write Fast Under Pressure</span>, <span style="font-style: italic;">The Art of E-Mail Writing</span>, and <span style="font-style: italic;">The Art of On-the-Job Writing</span>. He also writes the popular blog <span style="font-style: italic;">Words on the Line</span>, which offers practical tips for developing writers. Dr. Vassallo holds a B.A. in English, an M.S. in education, and a doctorate in educational theory.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/vassallo.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/vassallo.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (12981, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/void.jpg" alt="Photo of Richard Symansky" />Richard D. Symansky is a graduate of Amherst College and Boston University Law School. He has been a practicing attorney and Notary Public in New York State for over 40 years. His law practice has revolved around representation of financial institutions in a wide range of matters. He has more than 30 years experience teaching at the college level both in the SUNY system and for CFT and the American Institute of Banking. He has been helping people prepare for the Notary Public Licensing Exam for over 5 years. </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/void.jpg" alt="Photo of Richard Symansky" />Richard D. Symansky is a graduate of Amherst College and Boston University Law School. He has been a practicing attorney and Notary Public in New York State for over 40 years. His law practice has revolved around representation of financial institutions in a wide range of matters. He has more than 30 years experience teaching at the college level both in the SUNY system and for CFT and the American Institute of Banking. He has been helping people prepare for the Notary Public Licensing Exam for over 5 years. </p>', N'https://ttseast.blob.core.windows.net/images/presenters/void.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/void.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (14668, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/costonis.jpg" alt="Photo of Susan Costonis" />Susan Costonis is a compliance consultant and trainer. She specializes in compliance management along with deposit and lending regulatory training. Most of her 35-year career was spent as a banker in several areas including lending, marketing, compliance, and senior management. Susan has written numerous training manuals and successfully managed compliance programs and exams for institutions supervised by the OCC, FDIC, and Federal Reserve. She is a Certified Regulatory Compliance Manager, completed the ABA Graduate Compliance School, and graduated from the University of Akron and the Graduate Banking School of the University of Colorado. She regularly presents to financial institution audiences in several states.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/costonis.jpg" alt="Photo of Susan Costonis" />Susan Costonis is a compliance consultant and trainer. She specializes in compliance management along with deposit and lending regulatory training. Most of her 35-year career was spent as a banker in several areas including lending, marketing, compliance, and senior management. Susan has written numerous training manuals and successfully managed compliance programs and exams for institutions supervised by the OCC, FDIC, and Federal Reserve. She is a Certified Regulatory Compliance Manager, completed the ABA Graduate Compliance School, and graduated from the University of Akron and the Graduate Banking School of the University of Colorado. She regularly presents to financial institution audiences in several states.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/costonis.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/costonis.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (15002, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/faquir.jpg" alt="Photo of Asaad Faquir" />Asaad A. Faquir is currently a Compliance Officer in New England. His career in banking began in 2004 at a multi-billion dollar, publicly traded bank in South Florida where he was a VP Internal Consultant and trusted adviser to senior and executive management specializing in risk management, business efficiency and strategic alignment. In 2004 and 2005 he was a part of the management team analyzing and improving the results of the banks disaster recovery operations during and after Hurricanes Frances, Jeanne and Wilma.</p><p>Asaad has a BS in Finance from Florida State University, an MBA in Finance from Temple University and a Masters Degree in HR Management from the University of Limerick in Limerick, Ireland. He is a former Rotary International Foundation Ambassadorial Scholar and Adjunct Professor of HR Management.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/faquir.jpg" alt="Photo of Asaad Faquir" />Asaad A. Faquir is currently a Compliance Officer in New England. His career in banking began in 2004 at a multi-billion dollar, publicly traded bank in South Florida where he was a VP Internal Consultant and trusted adviser to senior and executive management specializing in risk management, business efficiency and strategic alignment. In 2004 and 2005 he was a part of the management team analyzing and improving the results of the banks disaster recovery operations during and after Hurricanes Frances, Jeanne and Wilma.</p><p>Asaad has a BS in Finance from Florida State University, an MBA in Finance from Temple University and a Masters Degree in HR Management from the University of Limerick in Limerick, Ireland. He is a former Rotary International Foundation Ambassadorial Scholar and Adjunct Professor of HR Management.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/faquir.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/faquir.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (15050, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/tinucci.jpg" alt="Photo of Joseph Tinucci" />Joseph D. Tinucci is the Assistant Treasurer for the University of Colorado. In this capacity he manages all of the Universitys banking relationships, directs the Universitys compliance efforts with regard to the Payment Card Industry Data Security Standard (PCIDSS), and consults internally on all aspects of cash flows and funds management. Prior to joining the University, he was an independent trainer and consultant working in the areas of electronic payments, treasury management, and payment and ecommerce security. </p><p>Joe has also been the CEO of a regional ACH Association, the President of a small community financial institution, and a staff auditor for a banking trade association. He is active in both the local and national trade associations for treasury management, and is on the Board of Directors of the Treasury Institute for Higher Education, a national association chartered to bring best practices in treasury management to colleges and universities.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/tinucci.jpg" alt="Photo of Joseph Tinucci" />Joseph D. Tinucci is the Assistant Treasurer for the University of Colorado. In this capacity he manages all of the Universitys banking relationships, directs the Universitys compliance efforts with regard to the Payment Card Industry Data Security Standard (PCIDSS), and consults internally on all aspects of cash flows and funds management. Prior to joining the University, he was an independent trainer and consultant working in the areas of electronic payments, treasury management, and payment and ecommerce security. </p><p>Joe has also been the CEO of a regional ACH Association, the President of a small community financial institution, and a staff auditor for a banking trade association. He is active in both the local and national trade associations for treasury management, and is on the Board of Directors of the Treasury Institute for Higher Education, a national association chartered to bring best practices in treasury management to colleges and universities.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/tinucci.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/tinucci.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (15167, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/tevans.jpg" alt="Photo of Troy Evans" />Troy D. Evans is a professional speaker and author and has been featured on Good Morning America, CNN, FOX and in The Washington Post, Chicago Tribune, Newsday, The New Yorker and more. Author of &quot;From Desperation to Dedication: An Ex-Cons Lessons on Turning Failure into Success&quot;</p><p>"Troy changed himself.  As a result, his stories and talk will immediately and effectively change every audience member.  I want everyone to hear him and his important message that I love."</p> <p><em> - Mark Victor Hansen, Co-Creator, #1 New York Times Best-Selling Series Chicken Soup for the Soul</em></p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/tevans.jpg" alt="Photo of Troy Evans" />Troy D. Evans is a professional speaker and author and has been featured on Good Morning America, CNN, FOX and in The Washington Post, Chicago Tribune, Newsday, The New Yorker and more. Author of &quot;From Desperation to Dedication: An Ex-Cons Lessons on Turning Failure into Success&quot;</p><p>"Troy changed himself.  As a result, his stories and talk will immediately and effectively change every audience member.  I want everyone to hear him and his important message that I love."</p> <p><em> - Mark Victor Hansen, Co-Creator, #1 New York Times Best-Selling Series Chicken Soup for the Soul</em></p>', N'https://ttseast.blob.core.windows.net/images/presenters/tevans.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/tevans.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (16304, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/solomon.jpg" alt="Photo of Mark Solomon" />Detective Mark Solomon is a 18 year veteran of the Greenwich Connecticut Police Department.  For the past 11 years, Det. Solomon has been assigned to the Greenwich Police Departments Criminal Investigation Division.  In December of 2008, Det. Solomon was assigned to the, "Connecticut Financial Crimes Task Force".  The Task Force has the authority to investigate all financially related crimes occurring in or having a nexus to the State of Connecticut.</p><p></p><p>Since March of 2009, Det. Solomon and the CT Financial Crimes Task Force have investigated a number of ATM Skimming incidents occurring in CT and along the along the Eastern Seaboard.  With the cooperative efforts of Local, State and Federal Law Enforcement, and various financial institutions, the task force has been able to arrested, or has assisted in the arrest of more than 30 suspects involved in ATM Skimming.  In April of 2009, Det. Solomon and the task force created an Intelligence Sharing Network in regards to ATM skimming.  Currently the network has more than 300 members from the law enforcement, financial institutions and ATM manufacturers across the country as well as a number of global participants.</p><p></p><p>Det.  Solomon has trained many law enforcement agencies as well as financial institutional employees and ATM manufacturers in regards to ATM Skimming Schemes.</p><p>Det. Solomon is also an active member of the International Association of Financial Crime Investigators (IAFCI).  In 2010, Det. Solomon received the IAFCIs CT Chapter Law Enforcement Officer of the Year award as well as the International MasterCard/IAFCI Law Enforcement Officer of the Year Award.  Currently, he is the CT Chapter President of the IAFCI.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/solomon.jpg" alt="Photo of Mark Solomon" />Detective Mark Solomon is a 18 year veteran of the Greenwich Connecticut Police Department.  For the past 11 years, Det. Solomon has been assigned to the Greenwich Police Departments Criminal Investigation Division.  In December of 2008, Det. Solomon was assigned to the, "Connecticut Financial Crimes Task Force".  The Task Force has the authority to investigate all financially related crimes occurring in or having a nexus to the State of Connecticut.</p><p></p><p>Since March of 2009, Det. Solomon and the CT Financial Crimes Task Force have investigated a number of ATM Skimming incidents occurring in CT and along the along the Eastern Seaboard.  With the cooperative efforts of Local, State and Federal Law Enforcement, and various financial institutions, the task force has been able to arrested, or has assisted in the arrest of more than 30 suspects involved in ATM Skimming.  In April of 2009, Det. Solomon and the task force created an Intelligence Sharing Network in regards to ATM skimming.  Currently the network has more than 300 members from the law enforcement, financial institutions and ATM manufacturers across the country as well as a number of global participants.</p><p></p><p>Det.  Solomon has trained many law enforcement agencies as well as financial institutional employees and ATM manufacturers in regards to ATM Skimming Schemes.</p><p>Det. Solomon is also an active member of the International Association of Financial Crime Investigators (IAFCI).  In 2010, Det. Solomon received the IAFCIs CT Chapter Law Enforcement Officer of the Year award as well as the International MasterCard/IAFCI Law Enforcement Officer of the Year Award.  Currently, he is the CT Chapter President of the IAFCI.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/solomon.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/solomon.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (16305, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/mccain.jpg" alt="Photo of Jim McCain" />Jim Mc Cain is a certified trainer and General Manager of Computer Information Development LLC. Jim became a certified trainer at California State University, Sacramento in 1999. Jim has 40 years direct experience in fraud prevention and remediation services. Jim started his career in 1971 with a small two state loan company called Universal Acceptance Corporation. Beginning as an office collector Jim ended his tenure at Univeral Acceptance as a senior manager. From there, Jim worked with Wells Fargo Bank in the auto lease department for 10 years. Jim spent the next 9 years with 2 different collection agencies in the California area; United Collection Service, Inc. in the Sacramento region and Platinum Recovery Service, Inc. in Orange County.</p><p>Jim then began working for American Recovery Service and Skipbusters, Inc in Sacramento from 1994 through sale of the companies to United Towing & Recovery Inc whose main office is in New York. Stayed with UTR for another 2 years in order to assist them in the final development of business practices throughout the United States.</p><p>In 2001 Jim joined Paul Campione and founded <b>Computer Information Development LLC (CID)</b> - now known as a leading firm providing exceptional services to national auto lenders throughout the United States.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/mccain.jpg" alt="Photo of Jim McCain" />Jim Mc Cain is a certified trainer and General Manager of Computer Information Development LLC. Jim became a certified trainer at California State University, Sacramento in 1999. Jim has 40 years direct experience in fraud prevention and remediation services. Jim started his career in 1971 with a small two state loan company called Universal Acceptance Corporation. Beginning as an office collector Jim ended his tenure at Univeral Acceptance as a senior manager. From there, Jim worked with Wells Fargo Bank in the auto lease department for 10 years. Jim spent the next 9 years with 2 different collection agencies in the California area; United Collection Service, Inc. in the Sacramento region and Platinum Recovery Service, Inc. in Orange County.</p><p>Jim then began working for American Recovery Service and Skipbusters, Inc in Sacramento from 1994 through sale of the companies to United Towing & Recovery Inc whose main office is in New York. Stayed with UTR for another 2 years in order to assist them in the final development of business practices throughout the United States.</p><p>In 2001 Jim joined Paul Campione and founded <b>Computer Information Development LLC (CID)</b> - now known as a leading firm providing exceptional services to national auto lenders throughout the United States.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/mccain.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/mccain.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (16323, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/dowdy.jpg" alt="Photo of Carolyn Dowdy" />Carolyn Dowdy has over 25 years experience in community banking. During her career, she served as part of the senior management team of two new start-up banks in Georgia. Her breadth of experience allowed her to make the leap to consulting on deposit operations and IT compliance issues with community banks in 2005 when she started Bank Project Solutions. Her insight into banking trends led her to develop a curriculum and compliance training materials for Remote Deposit Capture for financial institutions in 2006. She has since trained hundreds of bankers on these issues at financial institutions and in online forums for third-party technology service providers. Because of her specialized knowledge in compliance, she has also facilitated sessions at several bank organization seminars, for a data processing Users Group, and recently at a compliance school.</p><p>Carolyn wrote and self-published a book on Remote Deposit Capture in 2007, titled "Remote Deposit Capture, Task Lists &amp; Quick Reference Guide."&nbsp;&nbsp;This book was one of the first of its kind to provide needed guidance to financial institutions as they began implementing Remote Deposit Capture at their institutions. As well, she developed and launched her visionary website, RemoteDepositStore.com, to provide education and risk management tools to the financial industry.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/dowdy.jpg" alt="Photo of Carolyn Dowdy" />Carolyn Dowdy has over 25 years experience in community banking. During her career, she served as part of the senior management team of two new start-up banks in Georgia. Her breadth of experience allowed her to make the leap to consulting on deposit operations and IT compliance issues with community banks in 2005 when she started Bank Project Solutions. Her insight into banking trends led her to develop a curriculum and compliance training materials for Remote Deposit Capture for financial institutions in 2006. She has since trained hundreds of bankers on these issues at financial institutions and in online forums for third-party technology service providers. Because of her specialized knowledge in compliance, she has also facilitated sessions at several bank organization seminars, for a data processing Users Group, and recently at a compliance school.</p><p>Carolyn wrote and self-published a book on Remote Deposit Capture in 2007, titled "Remote Deposit Capture, Task Lists &amp; Quick Reference Guide."&nbsp;&nbsp;This book was one of the first of its kind to provide needed guidance to financial institutions as they began implementing Remote Deposit Capture at their institutions. As well, she developed and launched her visionary website, RemoteDepositStore.com, to provide education and risk management tools to the financial industry.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/dowdy.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/dowdy.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (16913, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/kelly.jpg" alt="Photo of Denis Kelly" />Denis G. Kelly is formerly an executive and partner of Originate Home Loans and 21st Century Mortgage Bankers (national mortgage bankers) as well as a $1 billion producer at Washington Mutual. He was featured in Broker Magazine for bringing unique and efficient distribution models to the banking industry and has been interviewed on FOX News, FOX Business, MSNBC, Reuters, and the Nightly Business Report. He has created software solutions for the banking, credit and identity theft industries.</p><p> Through his vast experience in all aspects of the banking industry, Kelly witnessed first-hand the horrific effect that identity theft has on both individuals and society. In addition to The Official Identity Theft Prevention Handbook, Kelly wrote "<i>An Identity Theft Paradise</i>", a whitepaper outlining the dangers and systematic failures regarding synthetic identity theft. Kelly has his Fair Credit Reporting Act certification from the Consumer Data Industry Association, Certified Identity Theft Risk Management Specialist certification from the Institute of Fraud Risk Management, and Certified Identity Expert designation from the Identity Ambassador Commission (IdentityAmbassador.org, an identity theft education and training organization he founded).</p><p>He is a consultant to IDValidation (CID LLC), the only company with direct interface to Social Security Administrations Master File/Death Index through SSAs Consent Based Social Security Number Verification (CBSV) service which mitigates fraud and identity theft, reduces loan losses and net charge-offs, thwarts bad/unwanted hires, and is a tool in meeting regulatory compliance requirements by matching personal identifiers to official governmental source records.</p><p>Additionally, he is founder and President of IDCuffs.com, an identity theft prevention company, and TheIDChannel.com, a centralized resource for all the latest news and information regarding identity theft. He has had numerous speaking engagements and is recognized as a leader in the field of identity theft. Denis G. Kelly lives in Miami, Florida.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/kelly.jpg" alt="Photo of Denis Kelly" />Denis G. Kelly is formerly an executive and partner of Originate Home Loans and 21st Century Mortgage Bankers (national mortgage bankers) as well as a $1 billion producer at Washington Mutual. He was featured in Broker Magazine for bringing unique and efficient distribution models to the banking industry and has been interviewed on FOX News, FOX Business, MSNBC, Reuters, and the Nightly Business Report. He has created software solutions for the banking, credit and identity theft industries.</p><p> Through his vast experience in all aspects of the banking industry, Kelly witnessed first-hand the horrific effect that identity theft has on both individuals and society. In addition to The Official Identity Theft Prevention Handbook, Kelly wrote "<i>An Identity Theft Paradise</i>", a whitepaper outlining the dangers and systematic failures regarding synthetic identity theft. Kelly has his Fair Credit Reporting Act certification from the Consumer Data Industry Association, Certified Identity Theft Risk Management Specialist certification from the Institute of Fraud Risk Management, and Certified Identity Expert designation from the Identity Ambassador Commission (IdentityAmbassador.org, an identity theft education and training organization he founded).</p><p>He is a consultant to IDValidation (CID LLC), the only company with direct interface to Social Security Administrations Master File/Death Index through SSAs Consent Based Social Security Number Verification (CBSV) service which mitigates fraud and identity theft, reduces loan losses and net charge-offs, thwarts bad/unwanted hires, and is a tool in meeting regulatory compliance requirements by matching personal identifiers to official governmental source records.</p><p>Additionally, he is founder and President of IDCuffs.com, an identity theft prevention company, and TheIDChannel.com, a centralized resource for all the latest news and information regarding identity theft. He has had numerous speaking engagements and is recognized as a leader in the field of identity theft. Denis G. Kelly lives in Miami, Florida.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/kelly.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/kelly.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (17349, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/pinkowish.jpg" alt="Photo of Thomas Pinkowish" />Thomas Pinkowish works in mortgage and consumer lending at the national, state, and local level as a lender, educator, and consultant.  Over his twenty-nine year career, Tom worked with regulators, government agencies, thrifts, community banks, credit unions, and national trade associations, as well as local and national mortgage companies.</p><p>As an educator, Tom served for fifteen years as Director of the National Mortgage Institute and Community Lending Institute for the American Bankers Association and Americas Community Bankers.  He serves as a Director for the Connecticut Mortgage Bankers Association and is its Education Committee co-chair. He also works in course evaluation and auditing for the Nationwide Mortgage Licensing System (NMLS) and was invited to help design the National Component of the SAFE MLO Test. </p><p>Tom has twenty years of experience designing and teaching courses for hundreds of bank, credit union, and mortgage banking employees, as well as their state and federal regulators. </p><p>As a lender and consultant, Tom worked  in lending and compliance with lenders ranging from $11 million to $70 billion in assets. He held management positions in: residential and consumer lending; secondary marketing;  loan servicing; compliance; and operations.  In addition to managing lending departments and staff, Toms experience includes: underwriting in over 31 states;  integrating mortgage banking operations into community banks; redesigning loan origination and servicing departments; and developing policies, procedures, and operations for residential, consumer, construction, income property, and secondary market lending.</p><p>Tom is on the board of directors of the CT Mortgage Bankers Association and a corporator for a CT community bank. He is a 1998 graduate of Americas Community Bankers National School of Banking and a 1992 honors graduate of the Connecticut School of Finance and Management.  </p><p>He published several articles individually and is author of the industry standard textbook, Residential Mortgage Lending, Principles and Practices (6th edition), published in May, 2011.</p><p></p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/pinkowish.jpg" alt="Photo of Thomas Pinkowish" />Thomas Pinkowish works in mortgage and consumer lending at the national, state, and local level as a lender, educator, and consultant.  Over his twenty-nine year career, Tom worked with regulators, government agencies, thrifts, community banks, credit unions, and national trade associations, as well as local and national mortgage companies.</p><p>As an educator, Tom served for fifteen years as Director of the National Mortgage Institute and Community Lending Institute for the American Bankers Association and Americas Community Bankers.  He serves as a Director for the Connecticut Mortgage Bankers Association and is its Education Committee co-chair. He also works in course evaluation and auditing for the Nationwide Mortgage Licensing System (NMLS) and was invited to help design the National Component of the SAFE MLO Test. </p><p>Tom has twenty years of experience designing and teaching courses for hundreds of bank, credit union, and mortgage banking employees, as well as their state and federal regulators. </p><p>As a lender and consultant, Tom worked  in lending and compliance with lenders ranging from $11 million to $70 billion in assets. He held management positions in: residential and consumer lending; secondary marketing;  loan servicing; compliance; and operations.  In addition to managing lending departments and staff, Toms experience includes: underwriting in over 31 states;  integrating mortgage banking operations into community banks; redesigning loan origination and servicing departments; and developing policies, procedures, and operations for residential, consumer, construction, income property, and secondary market lending.</p><p>Tom is on the board of directors of the CT Mortgage Bankers Association and a corporator for a CT community bank. He is a 1998 graduate of Americas Community Bankers National School of Banking and a 1992 honors graduate of the Connecticut School of Finance and Management.  </p><p>He published several articles individually and is author of the industry standard textbook, Residential Mortgage Lending, Principles and Practices (6th edition), published in May, 2011.</p><p></p>', N'https://ttseast.blob.core.windows.net/images/presenters/pinkowish.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/pinkowish.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (18053, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/demaio.jpg" alt="Photo of Jim DeMaio" /> Jim DeMaio is President of Learning Dynamics, a national training company now in its 31st year. Jim has presented hundreds of workshops of leadership, customer service, performance management, and employee relations. His practical approach provides participants with information that can be put to use immediately. </p><p> Prior to joining Learning Dynamics, Jim was Vice President and Director of Corporate Training for a financial institution in the northeast. Since joining Learning Dynamics, Jim has provided training sessions to many banks and has been a presenter at the National School of Banking for 15 years. </p><p> Jim holds a B.S. in Management from Quinnipiac University and an M.B.A. from the University of New Haven.</p> ', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/demaio.jpg" alt="Photo of Jim DeMaio" /> Jim DeMaio is President of Learning Dynamics, a national training company now in its 31st year. Jim has presented hundreds of workshops of leadership, customer service, performance management, and employee relations. His practical approach provides participants with information that can be put to use immediately. </p><p> Prior to joining Learning Dynamics, Jim was Vice President and Director of Corporate Training for a financial institution in the northeast. Since joining Learning Dynamics, Jim has provided training sessions to many banks and has been a presenter at the National School of Banking for 15 years. </p><p> Jim holds a B.S. in Management from Quinnipiac University and an M.B.A. from the University of New Haven.</p> ', N'https://ttseast.blob.core.windows.net/images/presenters/demaio.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/demaio.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (18276, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/behringer.jpg" alt="Photo of John Behringer" />John is a Certified Public Accountant dedicated to working with McGladreys Financial Institutions industry group. He has over 13 years of public accounting experience working specifically with commercial banks, both privately- and publicly-held, and de novo institutions, mortgage banks, investment companies and broker dealers. John focuses on providing advisory and risk management consulting services to commercial banks. John leads a regional Loan Review practice for the firm which provides loan review services to institutions with loan portfolios ranging in size from $100 million to in excess of $50 billion. He has extensive experience providing external audit, loan review and internal audit services that include credit administration risk management services; SEC, Sarbanes-Oxley, and FDICIA reporting issues; internal controls implementation; and, on-going compliance services.</p><p>In addition to his client service responsibilities, John serves as a Facilitator for McGladreys National Accounting and Advisory Services continuing education programs. He also regularly presents at various industrya and professional conferences on current banking and accounting issues.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/behringer.jpg" alt="Photo of John Behringer" />John is a Certified Public Accountant dedicated to working with McGladreys Financial Institutions industry group. He has over 13 years of public accounting experience working specifically with commercial banks, both privately- and publicly-held, and de novo institutions, mortgage banks, investment companies and broker dealers. John focuses on providing advisory and risk management consulting services to commercial banks. John leads a regional Loan Review practice for the firm which provides loan review services to institutions with loan portfolios ranging in size from $100 million to in excess of $50 billion. He has extensive experience providing external audit, loan review and internal audit services that include credit administration risk management services; SEC, Sarbanes-Oxley, and FDICIA reporting issues; internal controls implementation; and, on-going compliance services.</p><p>In addition to his client service responsibilities, John serves as a Facilitator for McGladreys National Accounting and Advisory Services continuing education programs. He also regularly presents at various industrya and professional conferences on current banking and accounting issues.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/behringer.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/behringer.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (18277, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/knight.jpg" alt="Photo of John Knight" />John concentrates his practice in the area of banking and the business practices of banks and bank holding companies. In particular, he focuses on community bank mergers and acquisitions, regulatory matters affecting banks, including enforcement actions and compliance issues, bank holding company formations, subchapter S conversions, shareholder transactions, and shareholder and director issues. John serves as counsel to several Wisconsin community banks and to Bankers Bank of Madison, Wisconsin. He is also General Counsel to the Wisconsin Bankers Association and, in that capacity, has been involved in drafting and reviewing legislation of interest to the banking industry.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/knight.jpg" alt="Photo of John Knight" />John concentrates his practice in the area of banking and the business practices of banks and bank holding companies. In particular, he focuses on community bank mergers and acquisitions, regulatory matters affecting banks, including enforcement actions and compliance issues, bank holding company formations, subchapter S conversions, shareholder transactions, and shareholder and director issues. John serves as counsel to several Wisconsin community banks and to Bankers Bank of Madison, Wisconsin. He is also General Counsel to the Wisconsin Bankers Association and, in that capacity, has been involved in drafting and reviewing legislation of interest to the banking industry.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/knight.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/knight.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (18279, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/sophiekelley.jpg" alt="Photo of Sophie Kelley" /><b>Current Position and Responsibilities</b></p><p>Sophie Kelley is a senior manager in Wipfli LLP’s financial institutions practice and brings extensive leadership experience to Wipfli and her clients. She has over 20 years of leadership experience in banking, wealth management, and small businesses, of which she has also been an owner. Sophie is passionate about creating highly successful teams of engaged employees committed to achieving their mission.</p><p><b>Past Experience</b></p><ul><li>President of a community banking group with a large national financial institution</li><li>President and CEO of a community bank with $400 million in total assets</li><li>President and CEO of a multifamily office and a single-family office</li><li>President and owner of a company providing information technology consulting services to Fortune 500 companies</li><li>Various positions in private banking and commercial banking, handling customer relationships and business development</li></ul>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/sophiekelley.jpg" alt="Photo of Sophie Kelley" /><b>Current Position and Responsibilities</b></p><p>Sophie Kelley is a senior manager in Wipfli LLP’s financial institutions practice and brings extensive leadership experience to Wipfli and her clients. She has over 20 years of leadership experience in banking, wealth management, and small businesses, of which she has also been an owner. Sophie is passionate about creating highly successful teams of engaged employees committed to achieving their mission.</p><p><b>Past Experience</b></p><ul><li>President of a community banking group with a large national financial institution</li><li>President and CEO of a community bank with $400 million in total assets</li><li>President and CEO of a multifamily office and a single-family office</li><li>President and owner of a company providing information technology consulting services to Fortune 500 companies</li><li>Various positions in private banking and commercial banking, handling customer relationships and business development</li></ul>', N'https://ttseast.blob.core.windows.net/images/presenters/sophiekelley.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/sophiekelley.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (18281, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/saber.jpg" alt="Photo of Terry Saber" />Terry has 30 years of experience in strategic planning, human resources, executive compensation, and executive coaching with family-owned, privately held, and publicly traded banks; state banking associations; and nonprofits.  Terry is a longtime banker, consultant, and educator.  For the last 17 years, she has focused extensively on facilitation and strategic planning throughout the United States and works closely with boards of directors and executive management.  Prior to founding her consulting company in 1992, Terry was on the Senior Management team of a family-owned $800 million bank where she formed and led the Internal Compliance Committee to work through a Formal Agreement with the Office of the Comptroller of the Currency (OCC), reporting directly to the Board of Directors.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/saber.jpg" alt="Photo of Terry Saber" />Terry has 30 years of experience in strategic planning, human resources, executive compensation, and executive coaching with family-owned, privately held, and publicly traded banks; state banking associations; and nonprofits.  Terry is a longtime banker, consultant, and educator.  For the last 17 years, she has focused extensively on facilitation and strategic planning throughout the United States and works closely with boards of directors and executive management.  Prior to founding her consulting company in 1992, Terry was on the Senior Management team of a family-owned $800 million bank where she formed and led the Internal Compliance Committee to work through a Formal Agreement with the Office of the Comptroller of the Currency (OCC), reporting directly to the Board of Directors.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/saber.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/saber.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (18308, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/gerano.jpg" alt="Photo of Walt Gerano" />Walt Gerano brings with him more than 28 years of financial sales and sales management experience and has been a Sales Development Expert with Anthony Cole Training Group for over 8 years. His webinars are delivered in an entertaining manner and he captures the engagement of his participants with his wit and open story-telling style. Walt personally coaches more than 50 salespeople across the country on how to achieve their sales goals and personal dreams.</p>  ', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/gerano.jpg" alt="Photo of Walt Gerano" />Walt Gerano brings with him more than 28 years of financial sales and sales management experience and has been a Sales Development Expert with Anthony Cole Training Group for over 8 years. His webinars are delivered in an entertaining manner and he captures the engagement of his participants with his wit and open story-telling style. Walt personally coaches more than 50 salespeople across the country on how to achieve their sales goals and personal dreams.</p>  ', N'https://ttseast.blob.core.windows.net/images/presenters/gerano.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/gerano.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (18309, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/na.jpg" alt="Photo of Chris Carlson" />Chris has been a sales development expert with ACTG for 15 years and currently sells as well as delivers sales training to hundreds of salespeople and managers across the nation. Prior to that, he had a long history in financial services as a sales person, sales manager and additionally, he was a partner in his own insurance agency. Chris strength in working with sales people and managers is in his ability to uncover and address specific <i>real deal</i> sales challenges with his participants so that <i>training</i> turns into action and learning. </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/na.jpg" alt="Photo of Chris Carlson" />Chris has been a sales development expert with ACTG for 15 years and currently sells as well as delivers sales training to hundreds of salespeople and managers across the nation. Prior to that, he had a long history in financial services as a sales person, sales manager and additionally, he was a partner in his own insurance agency. Chris strength in working with sales people and managers is in his ability to uncover and address specific <i>real deal</i> sales challenges with his participants so that <i>training</i> turns into action and learning. </p>', N'https://ttseast.blob.core.windows.net/images/presenters/na.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/na.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (19383, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/appelbaum.jpg" alt="Photo of Laurie  Appelbaum" />Laurie Appelbaum is a highly-focused and goal-oriented leader who is extremely energetic and outgoing. Possessing over 15 years of training, management, strategic planning, communications and conference development experience, she is a creative motivator with exceptional business acumen.</p><p>Laurie has a unique ability to recognize an organizations needs, helping them to strategize, brainstorm and identify business opportunities.  She will implement unique and on-target marketing, communications and advocacy programs to help ensure a positive return on your bottom line. </p><p>She possess a deep understanding of customer service, leadership, ACH Rules and Regulations, Fraud, Regulation E, and other payment-industry-related topics.</p><p>She obtained her Accredited ACH Professional (AAP) designation in 2002.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/appelbaum.jpg" alt="Photo of Laurie  Appelbaum" />Laurie Appelbaum is a highly-focused and goal-oriented leader who is extremely energetic and outgoing. Possessing over 15 years of training, management, strategic planning, communications and conference development experience, she is a creative motivator with exceptional business acumen.</p><p>Laurie has a unique ability to recognize an organizations needs, helping them to strategize, brainstorm and identify business opportunities.  She will implement unique and on-target marketing, communications and advocacy programs to help ensure a positive return on your bottom line. </p><p>She possess a deep understanding of customer service, leadership, ACH Rules and Regulations, Fraud, Regulation E, and other payment-industry-related topics.</p><p>She obtained her Accredited ACH Professional (AAP) designation in 2002.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/appelbaum.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/appelbaum.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (20621, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/cole.jpg" alt="Photo of Anthony Cole" />An author and seasoned business consultant, Tony Cole has successfully coached thousands of people. He brings proven wisdom and expertise to companies nationwide, illustrating a parallel between army basic training, a no-excuses mentality and the accountability required for excellent performance in the corporate world.  Tony graduated from the University of Connecticut with a degree in Education. A scholarship athlete, upon graduation Tony leveraged his experience to coach Iowa State University and University of Cincinnati athletic teams. He then spent more than 15 years in sales and sales management positions in the exercise equipment and insurance industries. This unique combination of coaching and selling led him to launch Anthony Cole Training in 1991, which builds sales cultures within organizations nationwide.</P>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/cole.jpg" alt="Photo of Anthony Cole" />An author and seasoned business consultant, Tony Cole has successfully coached thousands of people. He brings proven wisdom and expertise to companies nationwide, illustrating a parallel between army basic training, a no-excuses mentality and the accountability required for excellent performance in the corporate world.  Tony graduated from the University of Connecticut with a degree in Education. A scholarship athlete, upon graduation Tony leveraged his experience to coach Iowa State University and University of Cincinnati athletic teams. He then spent more than 15 years in sales and sales management positions in the exercise equipment and insurance industries. This unique combination of coaching and selling led him to launch Anthony Cole Training in 1991, which builds sales cultures within organizations nationwide.</P>', N'https://ttseast.blob.core.windows.net/images/presenters/cole.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/cole.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (21565, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/fragapane.jpg" alt="Photo of Sal Fragapane" />Sal Fragapane is a Certified Regulatory Compliance Manager (CRCM) and a Certified Anti Money Laundering Specialist (CAMS) who serves as the Chief Compliance Officer and Chief Operating Officer of AML RightSource LLC.</P><P>Sal maintains his Ohio life, health, and annuities license as well his Ohio personal lines property and casualty license. He received his MBA from Baldwin Wallace University and his BSBA from Bowling Green State University. Sal is also a graduate of the FBI Citizens Academy.</P><P>Sal has spent 23 years in financial services between Key Bank, Third Federal Savings and Loan, and with AML RightSource. His experience in the roles as an internal auditor, retail banker, loan officer, BSA officer, Chief Operating Officer, and Chief Compliance Officer has provided him with the experience and well-rounded insight needed to effectively serve his clients.</P><P>Sal has successfully managed and always improved compliance programs and exams for institutions regulated by the OCC, FDIC, FRB, OTS, NCUA, SEC, and FINRA. He spends his time working with banks, MSBs, private equity funds, and nonbank mortgage lenders as both a consultant and as their Virtual Compliance Officer. </P>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/fragapane.jpg" alt="Photo of Sal Fragapane" />Sal Fragapane is a Certified Regulatory Compliance Manager (CRCM) and a Certified Anti Money Laundering Specialist (CAMS) who serves as the Chief Compliance Officer and Chief Operating Officer of AML RightSource LLC.</P><P>Sal maintains his Ohio life, health, and annuities license as well his Ohio personal lines property and casualty license. He received his MBA from Baldwin Wallace University and his BSBA from Bowling Green State University. Sal is also a graduate of the FBI Citizens Academy.</P><P>Sal has spent 23 years in financial services between Key Bank, Third Federal Savings and Loan, and with AML RightSource. His experience in the roles as an internal auditor, retail banker, loan officer, BSA officer, Chief Operating Officer, and Chief Compliance Officer has provided him with the experience and well-rounded insight needed to effectively serve his clients.</P><P>Sal has successfully managed and always improved compliance programs and exams for institutions regulated by the OCC, FDIC, FRB, OTS, NCUA, SEC, and FINRA. He spends his time working with banks, MSBs, private equity funds, and nonbank mortgage lenders as both a consultant and as their Virtual Compliance Officer. </P>', N'https://ttseast.blob.core.windows.net/images/presenters/fragapane.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/fragapane.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (23860, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/c_crawford.jpg" alt="Photo of Christy Crawford" />Christy Crawford is the Vice President of Gettechnical, Inc. located in Baton Rouge, LA for the last 10 years. Formerly a trainer for Wal-Mart Corporation, Christy brings her previous 10 years of sales and training expertise to your financial institution. She has a Bachelors Degree in Speech Communication from Louisiana State University. She is BSA/AML certified and her expertise is in the deposit side of the financial institution. She specializes in teller, new accounts, IRA, robbery and security, and BSA training. She brings humor, youth, and vitality to the programs she teaches.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/c_crawford.jpg" alt="Photo of Christy Crawford" />Christy Crawford is the Vice President of Gettechnical, Inc. located in Baton Rouge, LA for the last 10 years. Formerly a trainer for Wal-Mart Corporation, Christy brings her previous 10 years of sales and training expertise to your financial institution. She has a Bachelors Degree in Speech Communication from Louisiana State University. She is BSA/AML certified and her expertise is in the deposit side of the financial institution. She specializes in teller, new accounts, IRA, robbery and security, and BSA training. She brings humor, youth, and vitality to the programs she teaches.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/c_crawford.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/c_crawford.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (24203, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/blake.jpg" alt="Photo of Ross Blake" />Ross Blake is a senior level trainer with 25 years of experience in designing and delivering training in conflict resolution, team building, performance feedback, meeting facilitation, and other communication skills.</p><p>His clients include several Fortune 500 companies as well as banks, manufacturing, service, military, and educational institutions. Its important to Ross that his participants learn skills so they can make positive changes in their banks and credit unions. He has spoken at industry conferences, including ABA, and before other business and training groups.<p>He is the author of  How to Give Employees Performance Feedback & Resolve Resistance, and is a graduate of Ohio University.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/blake.jpg" alt="Photo of Ross Blake" />Ross Blake is a senior level trainer with 25 years of experience in designing and delivering training in conflict resolution, team building, performance feedback, meeting facilitation, and other communication skills.</p><p>His clients include several Fortune 500 companies as well as banks, manufacturing, service, military, and educational institutions. Its important to Ross that his participants learn skills so they can make positive changes in their banks and credit unions. He has spoken at industry conferences, including ABA, and before other business and training groups.<p>He is the author of  How to Give Employees Performance Feedback & Resolve Resistance, and is a graduate of Ohio University.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/blake.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/blake.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (24210, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/swartzberg.jpg" alt="Photo of Sandy Swartzberg" />Sandys practice focuses on closely held businesses and all issues related to family-owned enterprises. He is skilled in mergers and acquisitions, business structures, and business agreements of all kinds.  A corporate strategist, Mr. Swartzbergs acumen includes serving as general counsel for a national trades association, and as a director of four for-profit businesses and three nonprofit businesses.  Mr. Swartzberg has also served on and advised numerous boards of directors as general counsel for the board.  In addition to his business expertise, Sandy is an IT pioneer in the legal field.  He was one of the first to recognize that IT requires not only knowledge of the law but a knowledge of IT, computers, and how they work together.</P>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/swartzberg.jpg" alt="Photo of Sandy Swartzberg" />Sandys practice focuses on closely held businesses and all issues related to family-owned enterprises. He is skilled in mergers and acquisitions, business structures, and business agreements of all kinds.  A corporate strategist, Mr. Swartzbergs acumen includes serving as general counsel for a national trades association, and as a director of four for-profit businesses and three nonprofit businesses.  Mr. Swartzberg has also served on and advised numerous boards of directors as general counsel for the board.  In addition to his business expertise, Sandy is an IT pioneer in the legal field.  He was one of the first to recognize that IT requires not only knowledge of the law but a knowledge of IT, computers, and how they work together.</P>', N'https://ttseast.blob.core.windows.net/images/presenters/swartzberg.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/swartzberg.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (25143, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/kavelaris.jpg" alt="Photo of Kris Kavelaris" />Kris, Broadbridges founder and President brings 38 years of business experience to the table. Hes done 3 startups, been the President, Chief Operating Officer, Chief Financial Officer of Companies owned by others, done audit, tax and consulting as a CPA, been a Project Manager in Computer Consulting, and done Turn-Around work for Companies in trouble. Hes been an "employee" for half his business career, a consultant for the other half. An operating guy at heart – hes run Manufacturing, run Marketing/Advertising/Selling, and personally sweat making Payroll. He brings the preceding experience to the M&A world. In his own words:</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/kavelaris.jpg" alt="Photo of Kris Kavelaris" />Kris, Broadbridges founder and President brings 38 years of business experience to the table. Hes done 3 startups, been the President, Chief Operating Officer, Chief Financial Officer of Companies owned by others, done audit, tax and consulting as a CPA, been a Project Manager in Computer Consulting, and done Turn-Around work for Companies in trouble. Hes been an "employee" for half his business career, a consultant for the other half. An operating guy at heart – hes run Manufacturing, run Marketing/Advertising/Selling, and personally sweat making Payroll. He brings the preceding experience to the M&A world. In his own words:</p>', N'https://ttseast.blob.core.windows.net/images/presenters/kavelaris.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/kavelaris.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (25154, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/hinkel.jpg" alt="Photo of Tom  Hinkel" />Tom Hinkel, Vice President of Compliance Services, is responsible for thought leadership on all compliance related internal and external initiatives. This includes contributions to the R&amp;D, quality control, and sales &amp; marketing departments. He is also responsible for ensuring that Safe Systems services incorporate and abide by appropriate financial industry regulations and best practices as well as serving as a regulatory compliance resource for Safe Systems customers. He is the author of the Compliance Guru website, and has 20+ years of experience in the banking industry. Hinkel holds a BA from Illinois Wesleyan University; an AA in computer programming; GSEC security certification from the SANS Institute; CISA and CRISC designations from ISACA, and the CCSA and CRMA designations from the IIA.</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/hinkel.jpg" alt="Photo of Tom  Hinkel" />Tom Hinkel, Vice President of Compliance Services, is responsible for thought leadership on all compliance related internal and external initiatives. This includes contributions to the R&amp;D, quality control, and sales &amp; marketing departments. He is also responsible for ensuring that Safe Systems services incorporate and abide by appropriate financial industry regulations and best practices as well as serving as a regulatory compliance resource for Safe Systems customers. He is the author of the Compliance Guru website, and has 20+ years of experience in the banking industry. Hinkel holds a BA from Illinois Wesleyan University; an AA in computer programming; GSEC security certification from the SANS Institute; CISA and CRISC designations from ISACA, and the CCSA and CRMA designations from the IIA.</p>', N'https://ttseast.blob.core.windows.net/images/presenters/hinkel.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/hinkel.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (25517, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/crawfordshelton.jpg" alt="Photo of Crawford Shelton" /><b>Honey Shelton</b> brings the best of both worlds to her speaking and training engagements. She has 25 years of experience as a training and quality improvement consultant for banks and banking associations across the country. Her banking background includes spending three years as Executive Vice President/Chief Retail Banking Officer with First Victoria National Bank. </p>  <p>Nationally recognized as an outstanding speaker, over a half million bankers have participated in programs Honey has presented. Her depth of knowledge, enthusiasm, and compelling personality has left her lasting mark on InterAction Training, the firm she founded in 1983. </p><p><b>Deborah Crawford</b> is the President of gettechnical inc. She specializes in compliance and regulations for the deposit side of financial institutions.  Her 20+ year career in banking and training began at Hibernia National Bank. She has been a seminar leader for many state associations and credit union groups across the nation.  She has Bachelors and Masters degrees from Louisiana State University.   </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/crawfordshelton.jpg" alt="Photo of Crawford Shelton" /><b>Honey Shelton</b> brings the best of both worlds to her speaking and training engagements. She has 25 years of experience as a training and quality improvement consultant for banks and banking associations across the country. Her banking background includes spending three years as Executive Vice President/Chief Retail Banking Officer with First Victoria National Bank. </p>  <p>Nationally recognized as an outstanding speaker, over a half million bankers have participated in programs Honey has presented. Her depth of knowledge, enthusiasm, and compelling personality has left her lasting mark on InterAction Training, the firm she founded in 1983. </p><p><b>Deborah Crawford</b> is the President of gettechnical inc. She specializes in compliance and regulations for the deposit side of financial institutions.  Her 20+ year career in banking and training began at Hibernia National Bank. She has been a seminar leader for many state associations and credit union groups across the nation.  She has Bachelors and Masters degrees from Louisiana State University.   </p>', N'https://ttseast.blob.core.windows.net/images/presenters/crawfordshelton.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/crawfordshelton.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (26360, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/rutkowski.jpg" alt="Photo of Rob Rutkowski" />Attorney, blogger, podcast producer and nationally-recognized speaker, Rob Rutkowski has recently migrated from being a partner in a law firm to being a speaker and solo practitioner. Rob advises credit unions on compliance, contract negotiation and employment law as well as a vast array of other legal issues. Rob is a well-known lecturer nationwide on topics such as lending compliance, social media and cloud computing, director and officer liability, disaster recovery, identity theft, credit union accounts and other laws impacting credit unions, such as the Bank Secrecy Act. He is a regular speaker at credit union leagues across the United States and has served as a speaker for CUNA, NAFCU and CUES. </p><p>A former member of the Board of Directors for the Lake County Educational Federal Credit Union, Rob remains very involved with the legal issues that matter to the credit union movement. He created the Current Issues in Credit Unions podcast (www.ciicu.com) and That Credit Union Blog (www.thatcreditunionblog.com). His new blog, Legal Complexity (www.legalcomplexity.com) should be available in the fall of 2013. He has been published in Credit Union Magazine, Credit Union Management Magazine, The Safety & Soundness Report, the Cleveland Bar Journal and The National List.</p><p>Rob earned his B.A. cum laude from the University of Akron in 1988 and his J.D. from the Case Western Reserve University School of Law in 1991. A member of the Cleveland Metropolitan Bar Association, he is licensed in Ohio and is admitted to practice before the U.S. District Court (Northern District of Ohio).</p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/rutkowski.jpg" alt="Photo of Rob Rutkowski" />Attorney, blogger, podcast producer and nationally-recognized speaker, Rob Rutkowski has recently migrated from being a partner in a law firm to being a speaker and solo practitioner. Rob advises credit unions on compliance, contract negotiation and employment law as well as a vast array of other legal issues. Rob is a well-known lecturer nationwide on topics such as lending compliance, social media and cloud computing, director and officer liability, disaster recovery, identity theft, credit union accounts and other laws impacting credit unions, such as the Bank Secrecy Act. He is a regular speaker at credit union leagues across the United States and has served as a speaker for CUNA, NAFCU and CUES. </p><p>A former member of the Board of Directors for the Lake County Educational Federal Credit Union, Rob remains very involved with the legal issues that matter to the credit union movement. He created the Current Issues in Credit Unions podcast (www.ciicu.com) and That Credit Union Blog (www.thatcreditunionblog.com). His new blog, Legal Complexity (www.legalcomplexity.com) should be available in the fall of 2013. He has been published in Credit Union Magazine, Credit Union Management Magazine, The Safety & Soundness Report, the Cleveland Bar Journal and The National List.</p><p>Rob earned his B.A. cum laude from the University of Akron in 1988 and his J.D. from the Case Western Reserve University School of Law in 1991. A member of the Cleveland Metropolitan Bar Association, he is licensed in Ohio and is admitted to practice before the U.S. District Court (Northern District of Ohio).</p>', N'https://ttseast.blob.core.windows.net/images/presenters/rutkowski.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/rutkowski.jpg')
GO
INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (26365, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/ringstrom.jpg" alt="Photo of David Ringstrom" />David Ringstrom, CPA owns Accounting Advisors, Inc., an Atlanta-based spreadsheet and database consulting firm that he started in 1991. David has written freelance articles about spreadsheets since 1996, some of which have been published internationally. He teaches dozens of webinars on Excel each year, along with speaking at conferences. David coined the phrase "Either you work Excel, or it works you!" Accordingly his sessions are designed to help you turn the tide and become a much more effective spreadsheet user. </p>', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/ringstrom.jpg" alt="Photo of David Ringstrom" />David Ringstrom, CPA owns Accounting Advisors, Inc., an Atlanta-based spreadsheet and database consulting firm that he started in 1991. David has written freelance articles about spreadsheets since 1996, some of which have been published internationally. He teaches dozens of webinars on Excel each year, along with speaking at conferences. David coined the phrase "Either you work Excel, or it works you!" Accordingly his sessions are designed to help you turn the tide and become a much more effective spreadsheet user. </p>', N'https://ttseast.blob.core.windows.net/images/presenters/ringstrom.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/ringstrom.jpg')
