INSERT [dbo].[Presenter] ([idUser], [Biography], [BiographyLong], [PhotoFull], [PhotoThumb]) VALUES (31270, N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/edwards.jpg" alt="Photo of Broc Edwards" />Broc Edwards helps leaders, teams, and organizations get better at the soft human stuff that drives hard business results: leadership, culture, strategy, innovation, communication, selection, and learning and development. As a consultant, coach, and training facilitator he has worked with individuals, teams, and leaders in manufacturing, mining, banking, retail, not-for-profit, and government organizations in North America, Europe, and Australia.</p><p> Prior to forming the two consultancies HRD Solutions and The Human Factor, Broc was SVP, Director of Learning & Leadership for a community bank. Additionally, he is a semi-active blogger and speaker on business, HR, and learning and development topics and has published the book What Thinks You? A Fool’s Eye View of Human Resources.</p> <p>When not working, traveling, or trying to keep up with his wife and kids, he can be found mountain biking and running the desert trails near his home in Northern Nevada.  </p>  ', N'<p><img class="alignleft" src="https://ttseast.blob.core.windows.net/images/presenters/edwards.jpg" alt="Photo of Broc Edwards" />Broc Edwards helps leaders, teams, and organizations get better at the soft human stuff that drives hard business results: leadership, culture, strategy, innovation, communication, selection, and learning and development. As a consultant, coach, and training facilitator he has worked with individuals, teams, and leaders in manufacturing, mining, banking, retail, not-for-profit, and government organizations in North America, Europe, and Australia.</p><p> Prior to forming the two consultancies HRD Solutions and The Human Factor, Broc was SVP, Director of Learning & Leadership for a community bank. Additionally, he is a semi-active blogger and speaker on business, HR, and learning and development topics and has published the book What Thinks You? A Fool’s Eye View of Human Resources.</p> <p>When not working, traveling, or trying to keep up with his wife and kids, he can be found mountain biking and running the desert trails near his home in Northern Nevada.  </p>  ', N'https://ttseast.blob.core.windows.net/images/presenters/edwards.jpg', N'https://ttseast.blob.core.windows.net/images/presenters/edwards.jpg')
